	// R| skip_if_not_installed("RPostgres")
	_ = runtime.MustCall(ctx, "skip_if_not_installed", runtime.PrimitiveArg(runtime.CharacterScalar("RPostgres")))

	// r2go: matrix-lowered block 2/28; original R follows.
	// R| library(sf)
	_ = runtime.MustCall(ctx, "library", runtime.PrimitiveArg(runtime.MustGlobal(ctx, "sf")))

	// r2go: matrix-lowered block 3/28; original R follows.
	// R| library(DBI)
	_ = runtime.MustCall(ctx, "library", runtime.PrimitiveArg(runtime.MustGlobal(ctx, "DBI")))

	// r2go: matrix-lowered block 4/28; original R follows.
	// R| library(RPostgreSQL)
	_ = runtime.MustCall(ctx, "library", runtime.PrimitiveArg(runtime.MustGlobal(ctx, "RPostgreSQL")))

	// r2go: matrix-lowered block 5/28; original R follows.
	// R| library(testthat)
	_ = runtime.MustCall(ctx, "library", runtime.PrimitiveArg(runtime.MustGlobal(ctx, "testthat")))

