const rtdal006683Source0001 = `test_that("we can read a shapefile using st_read", {
  nc <- st_read(system.file("shape/nc.shp", package = "sf"), "nc", crs = 4267, quiet = TRUE)
  expect_s3_class(nc, c("sf", "data.frame"), exact = TRUE)
  expect_equal(dim(nc), c(100, 15))
})`

const rtdal006683Source0002 = `test_that("we can read shapefiles with a query string", {
    nc <- st_read(system.file("shape/nc.shp", package="sf"), "nc", crs = 4267, quiet = TRUE)
    nc_all <- st_read(system.file("shape/nc.shp", package="sf"), query = "select * from nc", crs = 4267, quiet = TRUE)
    nc_some <- st_read(system.file("shape/nc.shp", package="sf"), query = "select * from nc where SID79 > 50", crs = 4267, quiet = TRUE)
})`

const rtdal006683Source0003 = `test_that("st_read.default gives error messages", {
  expect_error(st_read(), "dsn should specify a data source or filename")
  expect_error(st_read(NULL), "no st_read method available for objects of class NULL")
})`

const rtdal006683Source0004 = `test_that("st_write.sf gives error messages on unknown dsn", {
  expect_error(st_write(st_sf(st_sfc(st_point())), NULL), "no st_write method available for dsn of class NULL")
})`

const rtdal006683Source0005 = `test_that("stringsAsFactors = FALSE produces a data.frame with no factors", {
  nc <-  st_read(system.file("shape/nc.shp", package="sf"), "nc", crs = 4267,
                 stringsAsFactors = FALSE, quiet = TRUE)
  expect_false(any(sapply(nc, class) == "factor"))
})`

const rtdal006683Source0006 = `test_that("stringsAsFactors = TRUE produces a data.frame with factors", {
  nc <-  st_read(system.file("shape/nc.shp", package="sf"), "nc", crs = 4267,
                 stringsAsFactors = TRUE, quiet = TRUE)
  expect_true(any(sapply(nc, class) == "factor"))
})`

const rtdal006683Source0007 = `test_that("drivers extensions are all lowercase", {
  expect_equal(names(extension_map), tolower(names(extension_map)))
  expect_equal(names(prefix_map), tolower(names(prefix_map)))
})`

const rtdal006683Source0008 = `test_that("guess_driver is strict", {
  expect_error(guess_driver(c("PG:xyz", "x.shp")), "length")
  expect_error(guess_driver(1), "character")
})`

const rtdal006683Source0009 = "test_that(\"guess_driver works on extensions\", {\n  # for repeatability, this is how I turned the list to tests\n  # `^\"(\\w+)\" = (\"[\\w\\s]+\"),?`\n  # to `expect_equal(guess_driver(\"nc.\\1\"), c(\"\\1\" = \\2))`\n\n  expect_equal(guess_driver(\"nc.bna\"), c(\"bna\" = \"BNA\"))\n  expect_equal(guess_driver(\"nc.csv\"), c(\"csv\" = \"CSV\"))\n  expect_equal(guess_driver(\"nc.e00\"), c(\"e00\" = \"AVCE00\"))\n  expect_equal(guess_driver(\"nc.gdb\"), c(\"gdb\" = \"OpenFileGDB\"))\n  expect_equal(guess_driver(\"nc.geojson\"), c(\"geojson\" = \"GeoJSON\"))\n  expect_equal(guess_driver(\"nc.gml\"), c(\"gml\" = \"GML\"))\n  expect_equal(guess_driver(\"nc.gmt\"), c(\"gmt\" = \"GMT\"))\n  expect_equal(guess_driver(\"nc.gpkg\"), c(\"gpkg\" = \"GPKG\"))\n  expect_equal(guess_driver(\"nc.gps\"), c(\"gps\" = \"GPSBabel\"))\n  expect_equal(guess_driver(\"nc.gtm\"), c(\"gtm\" = \"GPSTrackMaker\"))\n  expect_equal(guess_driver(\"nc.gxt\"), c(\"gxt\" = \"Geoconcept\"))\n  expect_equal(guess_driver(\"nc.kml\"), c(\"kml\" = \"KML\"))\n  expect_equal(guess_driver(\"nc.jml\"), c(\"jml\" = \"JML\"))\n  expect_equal(guess_driver(\"nc.map\"), c(\"map\" = \"WAsP\"))\n  expect_equal(guess_driver(\"nc.mdb\"), c(\"mdb\" = \"Geomedia\"))\n  expect_equal(guess_driver(\"nc.nc\"), c(\"nc\" = \"netCDF\"))\n  expect_equal(guess_driver(\"nc.ods\"), c(\"ods\" = \"ODS\"))\n  expect_equal(guess_driver(\"nc.osm\"), c(\"osm\" = \"OSM\"))\n  expect_equal(guess_driver(\"nc.pbf\"), c(\"pbf\" = \"OSM\"))\n  expect_equal(guess_driver(\"nc.shp\"), c(\"shp\" = \"ESRI Shapefile\"))\n  expect_equal(guess_driver(\"nc.sqlite\"), c(\"sqlite\" = \"SQLite\"))\n  expect_equal(guess_driver(\"nc.vdv\"), c(\"vdv\" = \"VDV\"))\n  expect_equal(guess_driver(\"nc.xls\"), c(\"xls\" = \"xls\"))\n  expect_equal(guess_driver(\"nc.xlsx\"), c(\"xlsx\" = \"XLSX\"))\n\n  # unsuported\n  expect_equal(guess_driver(\"nc.notsupported\"), NA)\n})"

const rtdal006683Source0010 = "test_that(\"guess_driver works on suffixes\", {\n  # for repeatability, this is how I turned the list to tests\n  # `^\"(\\w+)\" = (\"[\\w\\s]+\"),?`\n  # to `expect_equal(guess_driver(\"nc.\\1\"), c(\"\\1\" = \\2))`\n\n  expect_equal(guess_driver(\"couchdb:nc\"), c(\"couchdb\" = \"CouchDB\"))\n  expect_equal(guess_driver(\"db2odbc:nc\"), c(\"db2odbc\" = \"DB2ODBC\"))\n  expect_equal(guess_driver(\"dods:nc\"), c(\"dods\" = \"DODS\"))\n  expect_equal(guess_driver(\"gft:nc\"), c(\"gft\" = \"GFT\"))\n  expect_equal(guess_driver(\"mssql:nc\"), c(\"mssql\" = \"MSSQLSpatial\"))\n  expect_equal(guess_driver(\"mysql:nc\"), c(\"mysql\" = \"MySQL\"))\n  expect_equal(guess_driver(\"oci:nc\"), c(\"oci\" = \"OCI\"))\n  expect_equal(guess_driver(\"odbc:nc\"), c(\"odbc\" = \"ODBC\"))\n  expect_equal(guess_driver(\"pg:nc\"), c(\"pg\" = \"PostgreSQL\"))\n  expect_equal(guess_driver(\"sde:nc\"), c(\"sde\" = \"SDE\"))\n\n  # upper case\n  expect_equal(guess_driver(\"CouchDB:nc\"), c(\"couchdb\" = \"CouchDB\"))\n  expect_equal(guess_driver(\"db2ODBC:nc\"), c(\"db2odbc\" = \"DB2ODBC\"))\n  expect_equal(guess_driver(\"DODS:nc\"), c(\"dods\" = \"DODS\"))\n  expect_equal(guess_driver(\"GFT:nc\"), c(\"gft\" = \"GFT\"))\n  expect_equal(guess_driver(\"MSSQL:nc\"), c(\"mssql\" = \"MSSQLSpatial\"))\n  expect_equal(guess_driver(\"MYSQL:nc\"), c(\"mysql\" = \"MySQL\"))\n  expect_equal(guess_driver(\"OCI:nc\"), c(\"oci\" = \"OCI\"))\n  expect_equal(guess_driver(\"ODBC:nc\"), c(\"odbc\" = \"ODBC\"))\n  expect_equal(guess_driver(\"PG:nc\"), c(\"pg\" = \"PostgreSQL\"))\n  expect_equal(guess_driver(\"SDE:nc\"), c(\"sde\" = \"SDE\"))\n\n  # unsuported\n  expect_equal(guess_driver(\"notsupported:nc\"), NA)\n})"

const rtdal006683Source0011 = `test_that("weird names are supported", {
  expect_equal(guess_driver("pg:nc.shp"), c("pg" = "PostgreSQL"))
  expect_equal(guess_driver("pg:nc.shp.e00"), c("pg" = "PostgreSQL"))
  expect_equal(guess_driver("nc.shp.e00"), c("e00" = "AVCE00"))
  expect_equal(guess_driver("couchdb:shp"), c("couchdb" = "CouchDB"))

  expect_equal(guess_driver("notsupported:nc.shp"), NA)
  expect_equal(guess_driver("notsupported"), NA)
})`

const rtdal006683Source0012 = `test_that("driver utils work", {
  expect_true(is_driver_available("shp", data.frame(name = c("x", "y", "shp"))))
  expect_true(is_driver_available("shp", data.frame(name = c("shp"))))
  expect_false(is_driver_available("shp", data.frame(name = c("x", "y", "z"))))
  expect_false(is_driver_available("shp", data.frame(name = c("x", "y", "z"))))

  expect_error(is_driver_can("shp", data.frame(name = c("x", "y", "shp")), operation = "nothing"))
  expect_error(is_driver_can("shp", data.frame(name = c("x", "y")), operation = "nothing"))
  expect_true(is_driver_can("shp", data.frame(name = c("x", "y", "shp"), write = rep(TRUE, 3)), operation = "write"))
  expect_false(is_driver_can("shp", data.frame(name = c("x", "y", "shp"), write = c(TRUE, TRUE, FALSE)), operation = "write"))
})`

const rtdal006683Source0013 = `test_that("guess_driver_can_write", {
  expect_error(guess_driver_can_write("x.e00", NA), "Could not guess")
  expect_error(guess_driver_can_write("x.not", c("nothing" = "nothing")), "not available")
  expect_equal(guess_driver_can_write("x.csv"), c("csv" = "CSV"))
  expect_equal(guess_driver_can_write("c:/x.csv"), c("csv" = "CSV"))

  expect_error(guess_driver_can_write("x.unsuported"), "Could not guess driver")
  expect_error(guess_driver_can_write("unsuported:x"), "Could not guess driver")
})`

const rtdal006683Source0014 = `test_that("driver operations", {
  # These tests are driver specifics to GDAL version and OS.
  expect_error(guess_driver_can_write("x.e00"), "AVCE00 driver not available|cannot write")
  # expect_error(guess_driver_can_write("x.gdb"), "cannot write") -> no longer the case when GDAL >= 3.6.0

  expect_equal(guess_driver_can_write("x.geojson"), c("geojson" = "GeoJSON"))
  expect_equal(guess_driver_can_write("x.csv"), c("csv" = "CSV"))
  expect_equal(guess_driver_can_write("x.gml"), c("gml" = "GML"))
})`

const rtdal006683Source0015 = `test_that("guess driver on windows with backslashes (#127)", {
    expect_identical(guess_driver("c:\\Temp\\this.shp"),
                     guess_driver("c:/Temp/this.shp"))
})`

