const rtdal006769Source0001 = ".apply <- function(data, col, fn, ...) {\n    .check_set_caller(\".apply\")\n    # pre-condition\n    .check_chr_within(\n        col,\n        within = names(data)\n    )\n    # select data do unpack\n    x <- data[col]\n    # prepare to unpack\n    x[[\"#..\"]] <- seq_len(nrow(data))\n    # unpack\n    x <- x |>\n        tidyr::unnest(cols = dplyr::all_of(col)) |>\n        dplyr::group_by(.data[[\"#..\"]])\n    # apply user function\n    x <- fn(x, ...)\n    # pack\n    x <- x |>\n        dplyr::ungroup() |>\n        tidyr::nest(`..unnest_col` = -\"#..\")\n    # remove garbage\n    x[[\"#..\"]] <- NULL\n    names(x) <- col\n    # prepare result\n    data[[col]] <- x[[col]]\n    data\n}"

const rtdal006769Source0004 = `.apply_across <- function(data, fn, ...) {
    # Pre-conditions
    .check_samples(data)
    # apply function
    .apply(data, col = "time_series", fn = function(x, ...) {
        dplyr::mutate(x, dplyr::across(
            dplyr::matches(.samples_bands(data)),
            fn, ...
        ))
    }, ...)
}`

const rtdal006769Source0005 = `.apply_capture_expression <- function(...) {
    # Capture dots as a list of quoted expressions
    list_expr <- lapply(
        substitute(list(...), env = environment()),
        unlist,
        recursive = FALSE
    )[-1L]

    # Check bands names from expression
    .check_expression(list_expr)

    # Get out band
    out_band <- toupper(gsub("_", "-", names(list_expr), fixed = TRUE))
    names(list_expr) <- out_band
    list_expr
}`

const rtdal006769Source0007 = `.apply_get_all_names <- function(expr) {
    if (is.call(expr)) {
        unique(unlist(lapply(as.list(expr)[-1L], .apply_get_all_names)))
    } else if (is.name(expr)) {
        paste0(expr)
    } else {
        character()
    }
}`

