const rtdal006774Source0020 = `.check_chr_within <- function(x,
                              within, ...,
                              case_sensitive = TRUE,
                              discriminator = "all_of",
                              can_repeat = TRUE,
                              msg = NULL) {
    # check parameter name
    param_x <- deparse(substitute(x, environment()))
    # make default message
    local_msg_x <- .message_invalid_param(param_x)

    # check within name
    param_w <- deparse(substitute(within, environment()))
    # make default message
    local_msg_w <- .message_invalid_param(param_w)

    # pre-condition
    .check_chr(
        within,
        len_min = 1L,
        local_msg = local_msg_w,
        msg = msg
    )
    # check parameters
    .check_discriminator(discriminator)
    # check type
    .check_chr_type(x, local_msg = local_msg_x, msg = msg)
    # check for repeated values
    if (!can_repeat) {
        .check_that(
            length(x) == length(unique(x)),
            local_msg = local_msg_x,
            msg = msg
        )
    }
    # simplify
    x <- unique(x)
    within <- unique(within)
    # transform inputs to verify without case sensitive
    if (!case_sensitive) {
        x <- tolower(x)
        within <- tolower(within)
    }
    # check discriminator
    switch(discriminator,
        one_of = .check_that(
            sum(x %in% within) == 1L,
            local_msg = local_msg_x,
            msg = msg
        ),
        any_of = .check_that(
            any(x %in% within),
            local_msg = local_msg_x,
            msg = msg
        ),
        all_of = .check_that(
            all(x %in% within),
            local_msg = local_msg_x,
            msg = msg
        ),
        none_of = .check_that(
            !any(x %in% within),
            local_msg = local_msg_x,
            msg = msg
        ),
        exactly = .check_that(
            all(x %in% within) && all(within %in% x),
            local_msg = local_msg_x,
            msg = msg
        )
    )
}`

const rtdal006774Source0021 = `.check_chr_contains <- function(x,
                                contains, ...,
                                case_sensitive = TRUE,
                                discriminator = "all_of",
                                can_repeat = TRUE,
                                msg = NULL) {
    # check parameter name
    var_x <- deparse(substitute(x, environment()))
    # make default message for param
    local_msg_x <- .message_invalid_param(var_x)
    # check type
    .check_chr_type(x, local_msg = local_msg_x)
    # check contains name
    var_cont <- deparse(substitute(contains, environment()))
    # make default message for param
    local_msg_cont <- .message_invalid_param(var_cont)
    # pre-condition
    .check_that(.has(contains), local_msg = local_msg_cont)
    # check discriminators
    .check_discriminator(discriminator)
    # check for repeated values
    if (!can_repeat) {
        .check_that(
            length(contains) == length(unique(contains)),
            local_msg = local_msg_cont,
            msg = msg
        )
    }
    # simplify
    x <- unique(x)
    contains <- unique(contains)
    # transform inputs to lower case
    if (!case_sensitive) {
        x <- tolower(x)
        contains <- tolower(contains)
    }
    # check discriminator
    switch(discriminator,
        one_of = .check_that(
            sum(contains %in% x) == 1L,
            local_msg = local_msg_x,
            msg = msg
        ),
        any_of = .check_that(
            any(contains %in% x),
            local_msg = local_msg_x,
            msg = msg
        ),
        all_of = .check_that(
            all(contains %in% x),
            local_msg = local_msg_x,
            msg = msg
        ),
        none_of = .check_that(
            !any(contains %in% x),
            local_msg = local_msg_x,
            msg = msg
        ),
        exactly = .check_that(
            all(contains %in% x) && all(x %in% contains),
            local_msg = local_msg_x,
            msg = msg
        )
    )
}`

const rtdal006774Source0022 = `.check_file <- function(x, ...,
                        extensions = NULL,
                        file_exists = TRUE,
                        local_msg = NULL,
                        msg = NULL) {
    # check parameter name
    parameter_name <- deparse(substitute(x, environment()))
    # make default message for param
    local_msg <- .message_invalid_param(parameter_name)

    # file extension
    ext_file <- function(x) {
        gsub(
            pattern = "[^?]+\\.([^?/.]+).*$",
            replacement = "\\1",
            basename(x)
        )
    }
    if (is.null(msg)) {
        # check parameter
        .check_chr(
            x,
            allow_na = FALSE,
            allow_empty = FALSE,
            len_min = 1L,
            allow_null = FALSE,
            local_msg = local_msg,
            msg = msg
        )
    }
    # check extension
    if (!is.null(extensions)) {
        extension <- ext_file(x)
        .check_that(extension %in% extensions,
            local_msg = local_msg
        )
    }
    if (file_exists) {
        existing_files <- file.exists(x)
        existing_dirs <- dir.exists(x)
        .check_that(
            all(existing_files | existing_dirs),
            local_msg = local_msg,
            msg = paste(
                .conf("messages", ".check_file_missing"),
                paste0("'", x[!existing_files], "'", collapse = ", ")
            )
        )
    } else {
        .check_that(
            x = suppressWarnings(file.create(x)),
            local_msg = local_msg,
            msg = .conf("messages", ".check_file_writable")
        )
    }
    invisible(x)
}`

const rtdal006774Source0023 = `.check_env_var <- function(x, ...,
                           local_msg = NULL,
                           msg = NULL) {
    # check parameter name
    parameter_name <- deparse(substitute(x, environment()))
    # make default message for param
    local_msg <- .message_invalid_param(parameter_name)
    # check env var exists
    .check_that(nchar(Sys.getenv(x)) > 0L, local_msg = local_msg)
    invisible(x)
}`

