const rtdal006778Source0001 = `.cluster_validity <- function(samples) {
    # set caller to show in errors
    .check_set_caller(".cluster_validity")
    # verifies if dtwclust package is installed
    .check_require_packages("dtwclust")
    # is the input data the result of a cluster function?
    .check_samples_cluster(samples)
    # compute CVIs and return
    dtwclust::cvi(
        a = factor(samples[["cluster"]]),
        b = factor(samples[["label"]]),
        type = "external",
        log.base = 10L
    )
}`

const rtdal006778Source0002 = `.cluster_dendrogram <- function(samples,
                                bands,
                                dist_method = "dtw_basic",
                                linkage = "ward.D2", ...) {
    # verifies if dtwclust package is installed
    .check_require_packages("dtwclust")
    # get the values of the time series
    values <- .values_ts(samples, bands, format = "cases_dates_bands")
    # call dtwclust and get the resulting dendrogram
    dendro <- dtwclust::tsclust(
        values,
        type = "hierarchical",
        k = max(nrow(samples) - 1L, 2L),
        distance = dist_method,
        control = dtwclust::hierarchical_control(method = linkage),
        ...
    )
    # return the dendrogram
    return(dendro)
}`

const rtdal006778Source0003 = ".cluster_dendro_bestcut <- function(samples, dendro) {\n    # compute range\n    k_range <- seq(2L, max(length(dendro[[\"height\"]]) - 1L, 2L))\n\n    # compute ARI for each k (vector)\n    ari <- k_range |>\n        purrr::map(function(k) {\n            x <- stats::cutree(dendro, k = k)\n            y <- factor(samples[[\"label\"]])\n            .cluster_rand_index(table(x, y))\n        }) |>\n        unlist()\n\n    # get the best ARI result\n    k_result <- k_range[which.max(ari)]\n\n    # compute each height corresponding to `k_result`\n    h_index <- length(dendro[[\"height\"]]) - k_result + 2L\n    h_result <- c(0L, dendro[[\"height\"]])[h_index]\n\n    # create a named vector and return\n    structure(c(k_result, h_result), .Names = c(\"k\", \"height\"))\n}"

