const rtdal006782Source0025 = `.conf_new_bands <- function(bands, config_fnc) {
    lapply(bands, function(band) {
        # lower case bands
        names(band) <- tolower(names(band))
        # configure band
        .check_error(
            {
                do.call(config_fnc, args = band)
            },
            msg = .conf("messages", ".conf_new_collection_bands")
        )
    })
}`

const rtdal006782Source0030 = `.conf_exists <- function(..., throw_error = FALSE) {
    key <- c(...)
    exists <- !is.null(.try(sits_env[["config"]][[key]], .default = NULL))
    if (!exists && throw_error) {
        stop("key '", paste(key, collapse = "->"), "' not found in config")
    }
    # Return test
    exists
}`

const rtdal006782Source0031 = `.conf <- function(...) {
    key <- c(...)
    # Check for key existence and throws an error if it not exists
    .conf_exists(key, throw_error = TRUE)
    sits_env[["config"]][[c(key)]]
}`

const rtdal006782Source0049 = `.conf_load_leaflet <- function() {
    leaf_map <- leaflet::leaflet() |>
        leaflet::addProviderTiles(
            provider = leaflet::providers[["Esri.WorldImagery"]],
            group = "ESRI"
        ) |>
        leaflet::addProviderTiles(
            provider = leaflet::providers[["OpenStreetMap"]],
            group = "OSM"
        ) |>
        leaflet::addWMSTiles(
            baseUrl = "https://tiles.maps.eox.at/wms/",
            layers = "s2cloudless-2023_3857",
            group = "Sentinel-2"
        )
    base_groups <- c("ESRI", "OSM", "Sentinel-2")
    # create a global object for leaflet control
    sits_leaflet <- list(
        leaf_map = leaf_map,
        base_groups = base_groups,
        overlay_groups = vector()
    )
    # put the object in the global sits environment
    sits_env[["leaflet"]] <- sits_leaflet

    # create a global object for controlling leaflet false color legend
    sits_env[["leaflet_false_color_legend"]] <- FALSE
    # create a global object for controlling leaflet SOM neuron color display
    sits_env[["leaflet_som_colors"]] <- FALSE
    invisible(sits_leaflet)
}`

