const rtdal006785Source0128 = `.cube_merge_tiles.raster_cube <- function(cube) {
    class_orig <- class(cube)
    cube <- tidyr::unnest(cube, "file_info", names_sep = ".")
    if (!inherits(cube, "derived_cube")) {
        cube <- dplyr::distinct(cube)
    }
    cube <- cube |>
        dplyr::arrange(
            .data[["file_info.date"]],
            .data[["file_info.band"]]
        ) |>
        tidyr::nest(
            file_info = tidyr::starts_with("file_info"),
            .names_sep = "."
        )
    # Set class features for the cube
    class(cube) <- class_orig
    # Return cube
    cube
}`

const rtdal006785Source0129 = `.cube_merge_tiles.derived_cube <- function(cube) {
    class_orig <- class(cube)
    cube <- cube |>
        tidyr::unnest("file_info", names_sep = ".") |>
        dplyr::arrange(
            .data[["file_info.start_date"]], .data[["file_info.band"]]
        ) |>
        tidyr::nest(
            file_info = tidyr::starts_with("file_info"),
            .names_sep = "."
        )
    # Set class features for the cube
    class(cube) <- class_orig
    # Return cube
    cube
}`

