const rtdal006794Source0004 = `.fi_type <- function(fi) {
    if ("date" %in% names(fi)) {
        "eo_cube"
    } else if (all(c("start_date", "end_date") %in% names(fi))) {
        "derived_cube"
    } else {
        stop(.conf("messages", ".fi_type"))
    }
}`

const rtdal006794Source0005 = `.fi_switch <- function(fi, ...) {
    switch(.fi_type(fi),
        ...
    )
}`

const rtdal006794Source0006 = `.fi_eo <- function(fid, band, date, ncols, nrows, xres, yres, xmin, xmax,
                   ymin, ymax, crs, path) {
    # Create a new eo file_info
    tibble::tibble(
        fid = fid,
        band = .band_eo(band),
        date = date,
        ncols = ncols,
        nrows = nrows,
        xres = xres,
        yres = yres,
        xmin = xmin,
        xmax = xmax,
        ymin = ymin,
        ymax = ymax,
        crs = crs,
        path = path
    )
}`

const rtdal006794Source0008 = `.fi_derived <- function(band, start_date, end_date, ncols, nrows, xres, yres,
                        xmin, xmax, ymin, ymax, path) {
    # Create a new derived file_info
    tibble::tibble(
        band = .band_derived(band),
        start_date = start_date,
        end_date = end_date,
        ncols = ncols,
        nrows = nrows,
        xres = xres,
        yres = yres,
        xmin = xmin,
        xmax = xmax,
        ymin = ymin,
        ymax = ymax,
        path = path
    )
}`

const rtdal006794Source0012 = `.fi_date_least_cloud_cover <- function(fi) {
    if ("cloud_cover" %in% colnames(fi)) {
        image <- fi |>
            dplyr::arrange(.data[["cloud_cover"]]) |>
            dplyr::slice(1L)
        as.Date(image[["date"]])
    } else {
        as.Date(.fi_timeline(fi))
    }
}`

const rtdal006794Source0013 = `.fi_filter_fid <- function(fi, fid) {
    .fi_switch(
        fi = fi,
        eo_cube = {
            fid_in_fi <- fid %in% .fi_fid(fi)
            if (!all(fid_in_fi)) {
                miss_fid <- paste0("'", fid[!fid_in_fi], "'", collapse = ",")
                stop("fid(s) ", miss_fid, " not found")
            }
            fi[.fi_fid(fi) %in% .as_chr(fid), ]
        }
    )
}`

