const rtdal006795Source0002 = `.gdal_params <- function(params) {
    .check_set_caller(".gdal_params")
    # Check if parameters are named
    .check_that(all(.has_name(params)))
    # gdalutils default value, sf gives error otherwise
    if (!.has(params)) {
        return(character(0))
    }
    unlist(mapply(function(par, val) {
        if (is.null(val)) {
            NULL
        } else if (is.logical(val)) {
            if (val) par else NULL
        } else if (is.list(val)) {
            c(par, unlist(val))
        } else {
            .as_chr(rbind(par, val))
        }
    }, names(params), unname(params), USE.NAMES = FALSE))
}`

const rtdal006795Source0003 = `.gdal_translate <- function(file, base_file, params,
                            conf_opts = character(0L), quiet) {
    sf::gdal_utils(
        util = "translate", source = base_file[[1L]], destination = file[[1L]],
        options = .gdal_params(params), config_options = conf_opts,
        quiet = quiet
    )
    invisible(file)
}`

const rtdal006795Source0004 = `.gdal_warp <- function(file, base_files, params,
                       quiet, conf_opts = character(0L)) {
    sf::gdal_utils(
        util = "warp", source = base_files, destination = file[[1L]],
        options = .gdal_params(params), config_options = conf_opts,
        quiet = quiet
    )
    return(invisible(file))
}`

const rtdal006795Source0006 = `.gdal_addo <- function(base_file) {
    conf_cog <- .conf("gdal_presets", "cog")
    sf::gdal_addo(
        file = base_file,
        method = conf_cog[["method"]],
        overviews = conf_cog[["overviews"]],
        options = c(GDAL_NUM_THREADS = "2")
    )
    invisible(file)
}`

const rtdal006795Source0007 = `.gdal_template_block <- function(block, bbox, file, nlayers, miss_value,
                                 data_type) {
    # Get first file
    file <- file[[1L]]
    # Convert to gdal data type
    data_type <- .gdal_data_type[[data_type]]
    # Output file
    file <- .try(
        {
            .gdal_translate(
                file = file,
                # GDAL does not allow raster creation, to bypass this limitation
                # We base our raster creation by using a tiny template
                # (647 Bytes)
                base_file = system.file(
                    "extdata/raster/gdal/template.tif",
                    package = "sits"
                ),
                params = list(
                    "-ot" = data_type,
                    "-of" = .conf("gdal_presets", "image", "of"),
                    "-b" = rep(1L, nlayers),
                    "-outsize" = list(.ncols(block), .nrows(block)),
                    "-scale" = list(0.0, 1.0, miss_value, miss_value),
                    "-a_srs" = .crs(bbox),
                    "-a_ullr" = list(
                        .xmin(bbox), .ymax(bbox), .xmax(bbox), .ymin(bbox)
                    ),
                    "-a_nodata" = miss_value,
                    "-co" = .conf("gdal_presets", "image", "co")
                ),
                quiet = TRUE
            )
        },
        .rollback = {
            unlink(file)
        },
        .finally = {
            # Delete auxiliary files
            unlink(paste0(file, ".aux.xml"))
        }
    )
    # Return file
    file
}`

const rtdal006795Source0008 = `.gdal_merge_into <- function(file, base_files, multicores, roi = NULL) {
    rast <- .raster_open_rast(file)
    # Merge src_files
    file <- .try(
        {
            if (.has(roi)) {
                # reproject ROI
                roi <- .roi_as_sf(roi, as_crs = .raster_crs(rast))
                # Write roi in a temporary file
                roi_file <- .roi_write(
                    roi = roi,
                    output_file = tempfile(fileext = ".shp"),
                    quiet = TRUE
                )
                .gdal_warp(
                    file = file,
                    base_files = base_files,
                    params = list(
                        "-wo" = paste0("NUM_THREADS=", multicores),
                        "-multi" = FALSE,
                        "-cutline" = roi_file,
                        "-q" = TRUE,
                        "-overwrite" = FALSE
                    ),
                    quiet = TRUE
                )
            } else {
                .gdal_warp(
                    file = file,
                    base_files = base_files,
                    params = list(
                        "-wo" = paste0("NUM_THREADS=", multicores),
                        "-multi" = FALSE,
                        "-q" = TRUE,
                        "-overwrite" = FALSE
                    ),
                    quiet = TRUE
                )
            }
        },
        .rollback = {
            unlink(file)
        },
        .finally = {
            # Delete auxiliary files
            unlink(paste0(file, ".aux.xml"))
            if (.has(roi)) .roi_delete(roi_file)
        }
    )
    # Return file
    return(file)
}`

const rtdal006795Source0009 = `.gdal_crop_image <- function(file,
                             out_file,
                             roi_file,
                             as_crs,
                             miss_value,
                             data_type,
                             multicores = 1L,
                             overwrite = TRUE, ...) {
    gdal_params <- list(
        "-ot" = .gdal_data_type[[data_type]],
        "-of" = .conf("gdal_presets", "image", "of"),
        "-co" = .conf("gdal_presets", "image", "co"),
        "-wo" = paste0("NUM_THREADS=", multicores),
        "-multi" = FALSE,
        "-t_srs" = as_crs,
        "-cutline" = roi_file,
        "-crop_to_cutline" = TRUE,
        "-dstnodata" = miss_value,
        "-overwrite" = overwrite
    )
    if (.has(.dissolve(list(...)))) {
        gdal_params <- utils::modifyList(gdal_params, as.list(...))
    }
    .gdal_warp(
        file = out_file, base_files = file,
        params = gdal_params, conf_opts = unlist(.conf("gdal_read_options")),
        quiet = TRUE
    )
    return(invisible(out_file))
}`

