const rtdal006796Source0001 = `.gc_arrange_images <- function(cube, timeline, period, ...) {
    UseMethod(".gc_arrange_images", cube)
}`

const rtdal006796Source0002 = `.gc_arrange_images.raster_cube <- function(cube, timeline, period, ...) {
    # include the end of last interval
    timeline <- c(
        timeline,
        timeline[[length(timeline)]] %m+% lubridate::period(period)
    )

    # filter and change image order according to cloud coverage
    .apply(cube, "file_info", function(x) {
        x <- dplyr::filter(
            x, .data[["date"]] >= timeline[[1]],
            .data[["date"]] < timeline[[length(timeline)]]
        )
        x <- dplyr::group_by(
            x,
            interval = cut(.data[["date"]], timeline, labels = FALSE),
            .add = TRUE
        )
        if ("cloud_cover" %in% names(x)) {
            x <- dplyr::arrange(
                x, .data[["cloud_cover"]],
                .by_group = TRUE
            )
        }
        dplyr::select(dplyr::ungroup(x), -"interval")
    })
}`

const rtdal006796Source0003 = `.gc_create_cube_view <- function(tile,
                                 period,
                                 res,
                                 roi,
                                 date,
                                 agg_method,
                                 resampling) {
    # set caller to show in errors
    .check_set_caller(".gc_create_cube_view")

    # pre-conditions
    .check_that(nrow(tile) == 1)


    # get bbox roi
    if (!is.null(roi)) {
        bbox_roi <- .bbox(roi, as_crs = .tile_crs(tile))
    } else {
        bbox_roi <- .tile_bbox(tile)
    }

    # create a gdalcubes extent
    extent <- list(
        left   = bbox_roi[["xmin"]],
        right  = bbox_roi[["xmax"]],
        bottom = bbox_roi[["ymin"]],
        top    = bbox_roi[["ymax"]],
        t0     = format(date, "%Y-%m-%d"),
        t1     = format(date, "%Y-%m-%d")
    )

    # create a list of cube views
    gdalcubes::cube_view(
        extent = extent,
        srs = .cube_crs(tile),
        dt = period,
        dx = res,
        dy = res,
        aggregation = agg_method,
        resampling = resampling
    )
}`

const rtdal006796Source0004 = `.gc_create_cloud_mask <- function(tile) {
    # set caller to show in errors
    .check_set_caller(".gc_create_cloud_mask")

    if (!.tile_contains_cloud(tile)) {
        return(NULL)
    }
    # create a image mask object
    mask_values <- suppressMessages(
        gdalcubes::image_mask(
            band = .source_cloud(),
            values = .source_cloud_interp_values(
                source = .cube_source(cube = tile),
                collection = .cube_collection(cube = tile)
            )
        )
    )
    # is this a bit mask cloud?
    if (.source_cloud_bit_mask(
        source = .cube_source(cube = tile),
        collection = .cube_collection(cube = tile)
    )) {
        mask_values <- list(
            band = .source_cloud(),
            min = 1,
            max = 2^16,
            bits = mask_values[["values"]],
            values = NULL,
            invert = FALSE
        )
    }

    class(mask_values) <- "image_mask"
    mask_values
}`

const rtdal006796Source0005 = ".gc_create_database_stac <- function(cube, path_db) {\n    # deleting the existing database to avoid errors in the stac database\n    if (file.exists(path_db)) {\n        unlink(path_db)\n    }\n\n    # use crs from tile if there is no crs in file_info\n    if (\"crs\" %in% names(.fi(cube))) {\n        file_info <- dplyr::select(cube, \"file_info\") |>\n            tidyr::unnest(cols = \"file_info\")\n    } else {\n        file_info <- dplyr::select(cube, \"file_info\", \"crs\") |>\n            tidyr::unnest(cols = \"file_info\")\n    }\n\n    # can be \"proj:epsg\" or \"proj:wkt2\"\n    crs_type <- .gc_detect_crs_type(file_info[[\"crs\"]][[1]])\n\n    file_info <- file_info |>\n        dplyr::transmute(\n            fid = .data[[\"fid\"]],\n            xmin = .data[[\"xmin\"]],\n            ymin = .data[[\"ymin\"]],\n            xmax = .data[[\"xmax\"]],\n            ymax = .data[[\"ymax\"]],\n            crs = .data[[\"crs\"]],\n            href = .data[[\"path\"]],\n            datetime = as.character(.data[[\"date\"]]),\n            band = .data[[\"band\"]],\n            !!crs_type := gsub(\"^EPSG:\", \"\", .data[[\"crs\"]])\n        )\n\n    features <- dplyr::mutate(file_info, id = .data[[\"fid\"]]) |>\n        tidyr::nest(features = -\"fid\")\n\n    features <- slider::slide_dfr(features, function(feat) {\n        bbox <- .bbox(feat[[\"features\"]][[1]][1, ], as_crs = \"EPSG:4326\")\n\n        feat[[\"features\"]][[1]] <- dplyr::mutate(feat[[\"features\"]][[1]],\n            xmin = bbox[[\"xmin\"]],\n            xmax = bbox[[\"xmax\"]],\n            ymin = bbox[[\"ymin\"]],\n            ymax = bbox[[\"ymax\"]]\n        )\n\n        feat\n    })\n\n    gc_data <- purrr::map(features[[\"features\"]], function(feature) {\n        feature <- feature |>\n            dplyr::select(-\"crs\") |>\n            tidyr::nest(assets = c(\"href\", \"band\")) |>\n            tidyr::nest(properties = c(\n                \"datetime\",\n                !!crs_type\n            )) |>\n            tidyr::nest(bbox = c(\n                \"xmin\", \"ymin\",\n                \"xmax\", \"ymax\"\n            ))\n\n        feature[[\"assets\"]] <- purrr::map(feature[[\"assets\"]], function(asset) {\n            asset |>\n                tidyr::pivot_wider(\n                    names_from = \"band\",\n                    values_from = \"href\"\n                ) |>\n                purrr::map(\n                    function(x) list(href = x, `eo:bands` = list(NULL))\n                )\n        })\n\n        feature <- unlist(feature, recursive = FALSE)\n        feature[[\"properties\"]] <- c(feature[[\"properties\"]])\n        feature[[\"bbox\"]] <- unlist(feature[[\"bbox\"]])\n        feature\n    })\n    gdalcubes::stac_image_collection(\n        s = gc_data,\n        out_file = path_db,\n        url_fun = identity\n    )\n}"

const rtdal006796Source0007 = `.gc_create_raster_cube <- function(cube_view, path_db, band, mask_band) {
    # set caller to show in errors
    .check_set_caller(".gc_create_raster_cube")
    # open db in each process
    path_db |>
        gdalcubes::image_collection() |>
        gdalcubes::raster_cube(
            view = cube_view,
            mask = mask_band,
            chunking = .conf("gdalcubes_chunk_size")
        ) |>
        gdalcubes::select_bands(
            bands = band
        )
}`

const rtdal006796Source0008 = `.gc_get_valid_timeline <- function(cube, period, extra_date_step = FALSE) {
    # set caller to show in errors
    .check_set_caller(".gc_get_valid_timeline")

    # start date - maximum of all minimums
    max_min_date <- do.call(
        what = max,
        args = purrr::map(cube[["file_info"]], function(file_info) {
            min(file_info[["date"]])
        })
    )
    # end date - minimum of all maximums
    min_max_date <- do.call(
        what = min,
        args = purrr::map(cube[["file_info"]], function(file_info) {
            max(file_info[["date"]])
        })
    )
    # check if all timeline of tiles intersects
    .check_that(max_min_date <= min_max_date)
    # define dates for period
    if (substr(period, 3, 3) == "M") {
        max_min_date <- lubridate::date(paste(
            lubridate::year(max_min_date),
            lubridate::month(max_min_date),
            "01",
            sep = "-"
        ))
    } else if (substr(period, 3, 3) == "Y") {
        max_min_date <- lubridate::date(paste(
            lubridate::year(max_min_date),
            "01", "01",
            sep = "-"
        ))
    }
    # generate timeline
    date <- lubridate::ymd(max_min_date)
    min_max_date <- lubridate::ymd(min_max_date)
    tl <- date
    repeat {
        date <- lubridate::ymd(date) %m+% lubridate::period(period)
        if (date > min_max_date) break
        tl <- c(tl, date)
    }
    # Add extra time step
    if (extra_date_step) {
        tl <- c(tl, tl[[length(tl)]] %m+% lubridate::period(period))
    }
    tl
}`

const rtdal006796Source0009 = ".gc_save_raster_cube <- function(raster_cube,\n                                 pack,\n                                 output_dir,\n                                 files_prefix, ...) {\n    # set caller to show in errors\n    .check_set_caller(\".gc_save_raster_cube\")\n\n    # convert sits gtiff options to gdalcubes format\n    gtiff_options <- strsplit(.conf(\"gdalcubes_options\"),\n        split = \"=\", fixed = TRUE\n    )\n    gdalcubes_co <- purrr::map(gtiff_options, `[[`, 2)\n    names(gdalcubes_co) <- purrr::map_chr(gtiff_options, `[[`, 1)\n\n    # get cog config parameters\n    generate_cog <- .conf(\"gdalcubes_cog_generate\")\n    cog_overview <- .conf(\"gdalcubes_cog_resample_overview\")\n\n    # write the aggregated cubes\n    img_paths <- suppressMessages(\n        gdalcubes::write_tif(\n            x = raster_cube,\n            dir = output_dir,\n            prefix = files_prefix,\n            creation_options = gdalcubes_co,\n            pack = pack,\n            COG = generate_cog,\n            rsmpl_overview = cog_overview, ...\n        )\n    )\n    # post-condition\n    .check_that(length(img_paths) >= 1)\n    img_paths\n}"

const rtdal006796Source0010 = `.gc_regularize <- function(cube,
                           timeline,
                           period,
                           res,
                           roi,
                           tiles,
                           output_dir,
                           multicores = 1,
                           progress) {
    # set caller to show in errors
    .check_set_caller(".gc_regularize")
    # require gdalcubes package
    .check_require_packages("gdalcubes")
    # prepare temp_output_dir
    temp_output_dir <- file.path(output_dir, ".sits")
    if (!dir.exists(temp_output_dir)) {
        dir.create(temp_output_dir, recursive = TRUE)
    }
    # set to delete all files in temp dir
    on.exit(unlink(list.files(temp_output_dir, full.names = TRUE)), add = TRUE)
    if (.has_not(timeline)) {
        # timeline of intersection
        timeline <- .gc_get_valid_timeline(cube, period = period)
    }
    # filter only intersecting tiles
    if (.has(roi)) {
        cube <- .cube_filter_spatial(cube, roi = roi)
    }
    if (.has(tiles)) {
        cube <- .cube_filter_tiles(cube, tiles = tiles)
    }
    # least_cc_first requires images ordered based on cloud cover
    cube <- .gc_arrange_images(
        cube = cube,
        timeline = timeline,
        period = period,
        roi = roi
    )
    # start processes
    .parallel_start(workers = multicores)
    on.exit(.parallel_stop(), add = TRUE)
    # does a local cube exist
    local_cube <- tryCatch(
        {
            sits_cube(
                source = .cube_source(cube),
                collection = .cube_collection(cube),
                data_dir = temp_output_dir,
                multicores = multicores,
                progress = progress
            )
        },
        error = function(e) {
            return(NULL)
        }
    )
    # find the tiles that have not been processed yet
    jobs <- .gc_missing_tiles(
        cube = cube,
        local_cube = local_cube,
        timeline = timeline
    )
    # recovery mode
    finished <- length(jobs) == 0

    while (!finished) {
        # for cubes that have a time limit to expire - mpc cubes only
        cube <- .cube_token_generator(cube)

        # process bands and tiles in parallel
        .parallel_map(jobs, function(job) {
            # get parameters from each job
            tile_name <- job[[1]]
            band <- job[[2]]
            date <- job[[3]]

            # we consider token is expired when the remaining time is
            # less than 5 minutes
            if (.cube_is_token_expired(cube)) {
                return(NULL)
            }

            # filter tile
            tile <- dplyr::filter(cube, .data[["tile"]] == !!tile_name)

            # filter roi
            tile_roi <- NULL

            if (.has(roi)) {
                tile_sf <- .cube_as_sf(tile)
                tile_roi <- .intersection(tile_sf, roi)

                # skip tile if there is no intersection with roi
                if (nrow(tile_roi) == 0) {
                    return(NULL)
                }
            }

            # post-condition
            .check_that(nrow(tile) == 1)

            # append gdalcubes path
            path_db <- tempfile(pattern = "gc", fileext = ".db")
            # create an image collection
            .gc_create_database_stac(cube = tile, path_db = path_db)
            # create a gdalcubes::cube_view
            cube_view <- .gc_create_cube_view(
                tile = tile,
                period = period,
                roi = tile_roi,
                res = res,
                date = date,
                agg_method = "first",
                resampling = "bilinear"
            )

            # create a gdalcubes::raster_cube object
            raster_cube <- .gc_create_raster_cube(
                cube_view = cube_view,
                path_db = path_db,
                band = band,
                mask_band = .gc_create_cloud_mask(tile)
            )

            # files prefix
            prefix <- paste(tile[["satellite"]],
                tile[["sensor"]],
                .cube_tiles(tile),
                band, "",
                sep = "_"
            )

            # check documentation mode
            progress <- .message_progress(progress)

            # gdalcubes log file
            gdalcubes_log_file <- file.path(tempdir(), "gdalcubes.log")
            # setting threads to process
            gdalcubes::gdalcubes_options(
                parallel = 2,
                debug = FALSE,
                log_file = gdalcubes_log_file,
                show_progress = progress
            )

            # create of the aggregate cubes
            tryCatch(
                {
                    .gc_save_raster_cube(
                        raster_cube = raster_cube,
                        pack = .gc_create_pack(cube = tile, band = band),
                        output_dir = temp_output_dir,
                        files_prefix = prefix
                    )
                },
                error = function(e) {
                    return(NULL)
                }
            )
        }, progress = progress)

        # create local cube from files in output directory
        local_cube <- tryCatch(
            {
                sits_cube(
                    source = .cube_source(cube),
                    collection = .cube_collection(cube),
                    data_dir = temp_output_dir,
                    multicores = multicores,
                    progress = FALSE
                )
            },
            error = function(e) {
                return(NULL)
            }
        )

        # find if there are missing tiles
        jobs <- .gc_missing_tiles(
            cube = cube,
            local_cube = local_cube,
            timeline = timeline
        )

        # have we finished?
        finished <- length(jobs) == 0

        # inform the user
        if (!finished) {
            # convert list of missing tiles and bands to a list of vectors
            tiles_bands <- purrr::transpose(jobs)
            tiles_bands <- purrr::map(tiles_bands, unlist)

            # get missing tiles
            bad_tiles <- unique(tiles_bands[[1]])

            # get missing bands per missing tile
            msg <- paste(
                bad_tiles,
                purrr::map_chr(bad_tiles, function(tile) {
                    paste0(
                        "(",
                        toString(
                            unique(
                                tiles_bands[[2]][tiles_bands[[1]] == tile]
                            )
                        ),
                        ")"
                    )
                }),
                collapse = ", "
            )

            # show message
            message("tiles", msg, "are missing or malformed", "
                    and will be reprocessed.")

            # remove cache
            .parallel_stop()
            .parallel_start(workers = multicores)
        }
    }
    # Crop files
    local_cube <- .crop(
        cube = local_cube,
        roi = roi,
        multicores = multicores,
        output_dir = output_dir,
        progress = progress
    )
    return(local_cube)
}`

const rtdal006796Source0012 = `.gc_missing_tiles <- function(cube, local_cube, timeline) {
    # do a cross product on tiles and bands
    tiles_bands_times <- unlist(slider::slide(cube, function(tile) {
        bands <- .cube_bands(tile, add_cloud = FALSE)
        tidyr::expand_grid(
            tile = .cube_tiles(tile), band = bands,
            time = timeline
        ) |>
            purrr::pmap(function(tile, band, time) {
                list(tile, band, time)
            })
    }), recursive = FALSE)

    # if regularized cube does not exist, return all tiles from original cube
    if (is.null(local_cube)) {
        return(tiles_bands_times)
    }

    # do a cross product on tiles and bands
    gc_tiles_bands_times <- unlist(slider::slide(local_cube, function(tile) {
        bands <- .cube_bands(tile, add_cloud = FALSE)
        tidyr::expand_grid(
            tile = .cube_tiles(tile), band = bands,
            time = timeline
        ) |>
            purrr::pmap(function(tile, band, time) {
                list(tile, band, time)
            })
    }), recursive = FALSE)

    # first, include tiles and bands that have not been processed
    miss_tiles_bands_times <-
        tiles_bands_times[!tiles_bands_times %in% gc_tiles_bands_times]

    # second, include tiles and bands that have been processed
    proc_tiles_bands_times <-
        tiles_bands_times[tiles_bands_times %in% gc_tiles_bands_times]

    # do all tiles and bands in local_cube have the same timeline as
    # the original cube?
    bad_timeline <- purrr::pmap_lgl(
        purrr::transpose(proc_tiles_bands_times),
        function(tile, band, date) {
            tile <- local_cube[local_cube[["tile"]] == tile, ]
            tile <- .select_raster_cube(tile, bands = band)
            !date %in% .tile_timeline(tile)
        }
    )

    # update malformed processed tiles and bands
    proc_tiles_bands_times <- proc_tiles_bands_times[bad_timeline]

    # return all tiles from the original cube
    # that have not been processed or regularized correctly
    unique(c(miss_tiles_bands_times, proc_tiles_bands_times))
}`

