const rtdal006798Source0006 = `.jobs_map_sequential <- function(jobs, fn, ...) {
    slider::slide(jobs, fn, ...)
}`

const rtdal006798Source0007 = `.jobs_map_sequential_chr <- function(jobs, fn, ...) {
    slider::slide_chr(jobs, fn, ...)
}`

const rtdal006798Source0008 = `.jobs_map_sequential_dfr <- function(jobs, fn, ...) {
    slider::slide_dfr(jobs, fn, ...)
}`

const rtdal006798Source0009 = `.jobs_map_parallel <- function(jobs, fn, ..., sync_fn = NULL,
                               progress = progress) {
    # Do split by rounds only if sync_fn is not NULL
    rounds <- .jobs_split(jobs)
    unlist(purrr::map(rounds, function(round) {
        if (!is.null(sync_fn)) {
            sync_fn(round)
        }
        round <- slider::slide(round, identity)
        .parallel_map(round, fn, ..., progress = progress)
    }), recursive = FALSE)
}`

const rtdal006798Source0010 = `.jobs_map_parallel_chr <- function(jobs, fn, ..., progress = progress) {
    values_lst <- .jobs_map_parallel(jobs, fn, ..., progress = progress)
    vapply(values_lst, c, NA_character_)
}`

const rtdal006798Source0011 = `.jobs_map_parallel_dfr <- function(jobs, fn, ..., progress = progress) {
    values_lst <- .jobs_map_parallel(jobs, fn, ..., progress = progress)
    dplyr::bind_rows(values_lst)
}`

