const rtdal006803Source0004 = `.message_warnings_colors_get <- function(missing, palette) {
    if (.message_warnings()) {
        miss_colors <- paste(.conf("messages", ".colors_get_missing"),
                        toString(missing))
        palette_str <- paste(.conf("messages", ".colors_get_missing_palette"),
                            palette)
        full_msg <- paste(miss_colors, "-", palette_str)
        warning(full_msg)
    }
}`

const rtdal006803Source0006 = `.message_warnings_regularize_cloud <- function(cube) {
    if (!all(.cube_contains_cloud(cube))) {
        if (.message_warnings()) {
            warning(.conf("messages", "sits_regularize_cloud"),
                call. = FALSE,
                immediate. = TRUE
            )
        }
    }
}`

const rtdal006803Source0007 = `.message_warnings_regularize_local <- function(cube) {
    if (!.cube_is_local(cube) && .message_warnings()) {
        warning(.conf("messages", "sits_regularize_local"),
            call. = FALSE, immediate. = TRUE
        )
    }
}`

