const rtdal006813Source0001 = `.plot_class_vector <- function(sf_seg,
                               legend,
                               palette,
                               scale,
                               tmap_params) {
    # set caller to show in errors
    .check_set_caller(".plot_class_vector")
    # check that segments have been classified
    .check_that("class" %in% colnames(sf_seg))
    # get the labels
    labels <- sf_seg |>
        sf::st_drop_geometry() |>
        dplyr::select("class") |>
        dplyr::distinct() |>
        dplyr::pull()
    names(labels) <- seq_along(labels)
    # obtain the colors
    colors <- .colors_get(
        labels = labels,
        legend = legend,
        palette = palette,
        rev = TRUE
    )
    # name the colors to match the labels
    names(colors) <- labels

    # plot
    .tmap_vector_class(
        sf_seg = sf_seg,
        colors = colors,
        scale = scale,
        tmap_params = tmap_params
    )
}`

const rtdal006813Source0002 = `.plot_probs_vector <- function(tile,
                               roi,
                               labels_plot,
                               palette,
                               rev,
                               scale,
                               tmap_params) {
    # set caller to show in errors
    .check_set_caller(".plot_probs_vector")
    # precondition - check color palette
    .check_palette(palette)
    # get all labels to be plotted
    labels <- .tile_labels(tile)
    names(labels) <- seq_along(labels)
    # check the labels to be plotted
    # if NULL, use all labels
    if (.has_not(labels_plot)) {
        labels_plot <- labels
    } else {
        .check_that(all(labels_plot %in% labels))
    }
    # retrieve the segments for this tile
    sf_seg <- .segments_read_vec(tile)
    # crop if there is a ROI
    if (.has(roi)) {
        sf_bbox <- sf::st_bbox(.roi_as_sf(roi))
        sf_seg <- sf::st_crop(sf_seg, sf_bbox)
        gc()
    }
    # plot the segments by facet
    .tmap_vector_probs(
        sf_seg = sf_seg,
        palette = palette,
        rev = rev,
        labels = labels,
        labels_plot = labels_plot,
        scale = scale,
        tmap_params = tmap_params
    )
}`

const rtdal006813Source0003 = `.plot_uncertainty_vector <- function(tile,
                                     roi,
                                     palette,
                                     rev,
                                     scale,
                                     tmap_params) {
    # precondition - check color palette
    .check_palette(palette)
    # obtain the uncertainty type
    uncert_type <- .vi(tile)[["band"]]

    # retrieve the segments for this tile
    sf_seg <- .segments_read_vec(tile)
    if (.has(roi)) {
        sf_bbox <- sf::st_bbox(.roi_as_sf(roi))
        sf_seg <- sf::st_crop(sf_seg, sf_bbox)
        gc()
    }
    # use tmap to plot uncertainty
    .tmap_vector_uncert(
        sf_seg = sf_seg,
        palette = palette,
        rev = rev,
        type = uncert_type,
        scale = scale,
        tmap_params = tmap_params
    )
}`

