const rtdal006816Source0017 = `.raster_open_rast <- function(file, ...) {
    # set caller to show in errors
    .check_set_caller(".raster_open_rast")
    rast <- suppressWarnings(
        terra::rast(x = .file_path_expand(file), ...)
    )
    .check_null_parameter(rast)
    # remove gain and offset applied by terra
    terra::scoff(rast) <- NULL
    rast
}`

const rtdal006816Source0018 = `.raster_write_rast <- function(rast,
                               file,
                               data_type,
                               overwrite, ...,
                               missing_value = NA) {
    # set caller to show in errors
    .check_set_caller(".raster_write_rast_terra")

    suppressWarnings(
        terra::writeRaster(
            x = rast,
            filename = path.expand(file),
            wopt = list(
                filetype = "GTiff",
                datatype = data_type,
                gdal = .conf("gdal_creation_options")
            ),
            NAflag = missing_value,
            overwrite = overwrite, ...
        )
    )
    # was the file written correctly?
    .check_file(file)
    return(invisible(rast))
}`

const rtdal006816Source0019 = `.raster_new_rast <- function(nrows,
                             ncols,
                             xmin,
                             xmax,
                             ymin,
                             ymax,
                             nlayers,
                             crs,
                             xres = NULL,
                             yres = NULL,
                             ...) {
    # prepare resolution
    resolution <- c(xres, yres)
    # prepare crs
    if (is.numeric(crs)) crs <- paste0("EPSG:", crs)
    # create new raster object if resolution is not provided
    if (is.null(resolution)) {
        # create a raster object
        rast <- suppressWarnings(
            terra::rast(
                nrows = nrows,
                ncols = ncols,
                nlyrs = nlayers,
                xmin  = xmin,
                xmax  = xmax,
                ymin  = ymin,
                ymax  = ymax,
                crs   = crs
            )
        )
    } else {
        # create a raster object
        rast <- suppressWarnings(
            terra::rast(
                nlyrs = nlayers,
                xmin = xmin,
                xmax = xmax,
                ymin = ymin,
                ymax = ymax,
                crs = crs,
                resolution = resolution
            )
        )
    }
    return(rast)
}`

const rtdal006816Source0020 = `.raster_read_rast <- function(files, ..., block = NULL, type = "numeric") {
    # check block
    if (.has(block)) {
        .check_raster_block(block = block)
    }
    # create raster objects
    rast <- .raster_open_rast(file = path.expand(files), ...)

    # start read
    if (.has_not(block)) {
        # read values
        terra::readStart(rast)
        values <- terra::readValues(
            x   = rast,
            mat = TRUE
        )
        # close file descriptor
        terra::readStop(rast)
    } else {
        # read values
        terra::readStart(rast)
        values <- terra::readValues(
            x = rast,
            row = block[["row"]],
            nrows = block[["nrows"]],
            col = block[["col"]],
            ncols = block[["ncols"]],
            mat = TRUE
        )
        # close file descriptor
        terra::readStop(rast)
    }
    if (type == "integer") {
        # convert to desired type
        storage.mode(values) <- type
    }
    return(values)
}`

const rtdal006816Source0021 = `.raster_crop <- function(rast,
                         file,
                         data_type,
                         overwrite,
                         mask,
                         missing_value = NA) {
    # pre-condition
    .check_null_parameter(mask)
    # check block
    if (.has_block(mask)) {
        .check_raster_block(block = mask)
    }
    # Update missing_value
    missing_value <- if (is.null(missing_value)) NA else missing_value
    # obtain coordinates from columns and rows
    # get extent
    if (.has_block(mask)) {
        xmin <- terra::xFromCol(
            object = rast,
            col = mask[["col"]]
        )
        xmax <- terra::xFromCol(
            object = rast,
            col = mask[["col"]] + mask[["ncols"]] - 1L
        )
        ymax <- terra::yFromRow(
            object = rast,
            row = mask[["row"]]
        )
        ymin <- terra::yFromRow(
            object = rast,
            row = mask[["row"]] + mask[["nrows"]] - 1L
        )

        # xmin, xmax, ymin, ymax
        extent <- c(
            xmin = xmin,
            xmax = xmax,
            ymin = ymin,
            ymax = ymax
        )
        mask <- .roi_as_sf(extent, default_crs = terra::crs(rast))
    }
    # in case of sf with another crs
    mask <- .roi_as_sf(mask, as_crs = terra::crs(rast))

    # crop raster
    suppressWarnings(
        terra::mask(
            x = rast,
            mask = terra::vect(mask),
            filename = path.expand(file),
            wopt = list(
                filetype = "GTiff",
                datatype = data_type,
                gdal = .conf("gdal_creation_options")
            ),
            NAflag = missing_value,
            overwrite = overwrite
        )
    )
}`

const rtdal006816Source0022 = `.raster_crop_metadata <- function(rast, ..., block = NULL, bbox = NULL) {
    # set caller to show in errors
    .check_set_caller(".raster_crop_metadata")
    # pre-condition
    .check_that(.has_not(block) || .has_not(bbox))
    # check block
    if (.has(block)) {
        .check_raster_block(block = block)
    }
    # check bbox
    if (.has(bbox)) {
        .check_raster_bbox(bbox = bbox)
    }
    # obtain coordinates from columns and rows
    if (!is.null(block)) {
        # get extent
        xmin <- terra::xFromCol(
            object = rast,
            col = block[["col"]]
        )
        xmax <- terra::xFromCol(
            object = rast,
            col = block[["col"]] + block[["ncols"]] - 1L
        )
        ymax <- terra::yFromRow(
            object = rast,
            row = block[["row"]]
        )
        ymin <- terra::yFromRow(
            object = rast,
            row = block[["row"]] + block[["nrows"]] - 1L
        )
    } else if (!is.null(bbox)) {
        xmin <- bbox[["xmin"]]
        xmax <- bbox[["xmax"]]
        ymin <- bbox[["ymin"]]
        ymax <- bbox[["ymax"]]
    }

    # xmin, xmax, ymin, ymax
    extent <- terra::ext(x = c(xmin, xmax, ymin, ymax))

    # crop raster
    suppressWarnings(
        terra::crop(x = rast, y = extent, snap = "out")
    )
}`

