const rtdal006816Source0033 = `.raster_scale <- function(rast, ...) {
    # check value
    i <- 1L
    while (is.na(rast[i])) {
        i <- i + 1L
    }
    value <- rast[i]
    if (value > 1.0 && value <= 10000L) {
        scale_factor <- 0.0001
    } else {
        scale_factor <- 1.0
    }
    scale_factor
}`

const rtdal006816Source0034 = `.raster_crs <- function(rast, ...) {
    crs <- suppressWarnings(
        terra::crs(x = rast, describe = TRUE)
    )
    if (!is.na(crs[["code"]])) {
        return(paste(crs[["authority"]], crs[["code"]], sep = ":"))
    }
    suppressWarnings(
        as.character(terra::crs(x = rast))
    )
}`

const rtdal006816Source0035 = `.raster_bbox <- function(rast, ...,
                         block = NULL) {
    if (is.null(block)) {
        # return a named bbox
        bbox <- c(
            xmin = .raster_xmin(rast),
            ymin = .raster_ymin(rast),
            xmax = .raster_xmax(rast),
            ymax = .raster_ymax(rast)
        )
    } else {
        r_crop <- .raster_crop_metadata(
            .raster_rast(rast = rast),
            block = block
        )
        bbox <- .raster_bbox(r_crop)
    }

    return(bbox)
}`

