const rtdal006819Source0001 = `.reg_cube <- function(cube, timeline, res, roi, period, output_dir, progress) {
    # Save input cube class
    cube_class <- class(cube)
    # Get timeline for the cube
    if (.has_not(timeline)) {
        timeline <- .gc_get_valid_timeline(
            cube = cube, period = period
        )
    }
    # Update token (for big tiffs and slow networks)
    cube <- .cube_token_generator(cube)
    # Create assets as jobs
    cube_assets <- .reg_cube_split_assets(
        cube = cube, period = period, timeline = timeline
    )
    # Process each tile sequentially
    cube_assets <- .jobs_map_parallel_dfr(cube_assets, function(asset) {
        # Update assets class to match cube class
        class(cube_assets) <- cube_class
        # Update token (for big tiffs and slow networks)
        cube_assets <- .cube_token_generator(cube_assets)
        # Manage s2 geometry
        # hold s2 status
        s2_status <- sf::sf_use_s2()
        # Disable for applicable cubes
        cube <- .cube_geometry_use_s2(cube, FALSE)
        # Before exit, restore s2 status
        on.exit(.cube_geometry_use_s2(cube, s2_status))
        # Merge assets
        .reg_merge_asset(
            asset = asset,
            res = res,
            roi = roi,
            output_dir = output_dir
        )
    }, progress = progress)
    # Check result
    .check_empty_data_frame(cube_assets)
    # Prepare cube output
    cube <- .cube_merge_tiles(cube_assets)
    .set_class(cube, cube_class)
}`

const rtdal006819Source0002 = `.reg_cube_split_assets <- function(cube, period, timeline) {
    # include the end of last interval to get the next images from the
    # last interval
    timeline <- c(
        timeline,
        timeline[[length(timeline)]] %m+% lubridate::period(period)
    )
    # Create assets data cube
    .cube_foreach_tile(cube, function(tile) {
        fi <- .fi_filter_interval(
            fi = .fi(tile),
            start_date = timeline[[1]],
            end_date = timeline[[length(timeline)]] - 1
        )
        groups <- cut(
            x = .fi_timeline(fi),
            breaks = timeline,
            labels = FALSE
        )
        fi_groups <- unname(split(fi, groups))
        assets <- .common_size(
            .discard(tile, "file_info"),
            feature = timeline[unique(groups)],
            file_info = fi_groups
        )
        assets <- assets[, c("tile", "feature", "file_info")]
        assets <- tidyr::unnest(assets, "file_info")
        assets[["asset"]] <- assets[["band"]]
        assets <- tidyr::nest(
            assets,
            file_info = -c("tile", "feature", "asset")
        )
        assets <- .common_size(
            .discard(tile, "file_info"),
            .discard(assets, "tile")
        )
        # Compare to original timeline
        origin_tl <- timeline[seq_along(timeline) - 1L]
        empty_dates <- as.Date(setdiff(origin_tl, unique(assets[["feature"]])))
        temp_date <- assets[1L, "feature"][[1L]]
        empty_files <- purrr::map_dfr(empty_dates, function(date) {
            temp_df <- assets[assets[["feature"]] == temp_date, ]
            temp_df[["feature"]] <- date
            temp_df[["file_info"]] <-
                purrr::map(temp_df[["file_info"]], function(fi) {
                    fi[["path"]] <- NA
                    fi
                })
            temp_df
        })
        assets <- dplyr::arrange(
            dplyr::bind_rows(assets, empty_files), .data[["feature"]]
        )
        .check_that(
            nrow(assets) == length(origin_tl) * length(.tile_bands(tile))
        )
        assets
    })
}`

const rtdal006819Source0003 = `.reg_merge_asset <- function(asset, res, roi, output_dir) {
    # Get band conf missing value
    band_conf <- .tile_band_conf(asset, band = asset[["asset"]])
    # Prepare output file name
    out_file <- .file_eo_name(
        tile = asset,
        band = asset[["asset"]],
        date = asset[["feature"]],
        output_dir = output_dir
    )
    fid_name <- paste(
        asset[["satellite"]], asset[["sensor"]], asset[["feature"]],
        sep = "_"
    )
    # Resume feature
    if (file.exists(out_file)) {
        .check_recovery()
        asset <- .tile_eo_from_files(
            files = out_file,
            fid = fid_name,
            bands = asset[["asset"]],
            date = asset[["feature"]],
            base_tile = .discard(asset, cols = c("asset", "feature")),
            update_bbox = TRUE
        )
        return(asset)
    }

    # Create template based on tile metadata
    if (.has_not(roi)) {
        roi <- .bbox_as_sf(.tile_bbox(asset))
    }
    roi_bbox <- .bbox(sf::st_intersection(
        x = .roi_as_sf(roi, as_crs = .crs(asset)),
        y = .bbox_as_sf(.bbox(asset))
    ))
    block <- list(
        ncols = floor((.xmax(roi_bbox) - .xmin(roi_bbox)) / res),
        nrows = floor((.ymax(roi_bbox) - .ymin(roi_bbox)) / res)
    )
    bbox <- list(
        xmin = .xmin(roi_bbox),
        xmax = .xmin(roi_bbox) + .ncols(block) * res,
        ymin = .ymax(roi_bbox) - .nrows(block) * res,
        ymax = .ymax(roi_bbox),
        crs = .crs(roi_bbox)
    )
    out_file <- .gdal_template_block(
        block = block,
        bbox = bbox,
        file = out_file,
        nlayers = 1L,
        miss_value = .miss_value(band_conf),
        data_type = .data_type(band_conf)
    )
    if (.has(.tile_paths(asset, bands = asset[["asset"]]))) {
        # Merge source files into template
        out_file <- .gdal_merge_into(
            file = out_file,
            base_files = .tile_paths(asset, bands = asset[["asset"]]),
            multicores = 2,
            roi = roi
        )
    }
    .tile_eo_from_files(
        files = out_file,
        fid = fid_name,
        bands = asset[["asset"]],
        date = asset[["feature"]],
        base_tile = .discard(asset, cols = c("asset", "feature")),
        update_bbox = TRUE
    )
}`

const rtdal006819Source0005 = ".reg_tile_convert.raster_cube <- function(cube, grid_system,\n                                          roi = NULL, tiles = NULL) {\n    # for consistency, check if the grid is already in place\n    if (grid_system == .cube_grid_system(cube)) {\n        return(cube)\n    }\n    # if roi and tiles are not provided, use the whole cube as extent\n    if (.has_not(roi) && .has_not(tiles)) {\n        roi <- .cube_as_sf(cube)\n    }\n\n    # generate system grid tiles and intersects it with roi\n    tiles_filtered <- .grid_filter_tiles(\n        grid_system = grid_system, tiles = tiles, roi = roi\n    )\n    tiles_filtered_crs <- unique(tiles_filtered[[\"crs\"]])\n\n    # bind all files\n    cube_fi <- dplyr::bind_rows(cube[[\"file_info\"]])\n\n    # get current cube class\n    cube_class <- class(cube)\n\n    # get reference files of each ``fid``\n    cube_fi_unique <- dplyr::distinct(\n        .data = cube_fi,\n        .data[[\"fid\"]], .data[[\"xmin\"]],\n        .data[[\"ymin\"]], .data[[\"xmax\"]],\n        .data[[\"ymax\"]], .data[[\"crs\"]]\n    )\n\n    # if unique crs pre-calculate bbox\n    fi_bbox <- NULL\n\n    if (length(tiles_filtered_crs) == 1L) {\n        # extract bounding box from files\n        fi_bbox <-  suppressWarnings(\n            .bbox_as_sf(.bbox(\n                x = cube_fi_unique,\n                default_crs = .crs(cube),\n                by_feature = TRUE\n            ), as_crs = tiles_filtered_crs)\n        )\n    }\n\n    # redistribute data into tiles\n    cube <- tiles_filtered |>\n        dplyr::rowwise() |>\n        dplyr::group_map(~ {\n            # prepare a sf object representing the bbox of each image in\n            # file_info\n            if (.has_not(fi_bbox)) {\n                fi_bbox <-  suppressWarnings(\n                    .bbox_as_sf(.bbox(\n                        x = cube_fi_unique,\n                        default_crs = .crs(cube),\n                        by_feature = TRUE\n                    ), as_crs = .x[[\"crs\"]])\n                )\n            }\n            # check intersection between files and tile\n            fids_in_tile <- cube_fi_unique[.intersects(fi_bbox, .x), ]\n            # get fids in tile\n            file_info <- cube_fi[cube_fi[[\"fid\"]] %in% fids_in_tile[[\"fid\"]], ]\n            # create cube!\n            .cube_create(\n                source = .tile_source(cube),\n                collection = .tile_collection(cube),\n                satellite = .tile_satellite(cube),\n                sensor = .tile_sensor(cube),\n                tile = .x[[\"tile_id\"]],\n                xmin = .xmin(.x),\n                xmax = .xmax(.x),\n                ymin = .ymin(.x),\n                ymax = .ymax(.x),\n                crs = .x[[\"crs\"]],\n                file_info = file_info\n            )\n        }) |>\n        dplyr::bind_rows()\n\n    # filter non-empty file info\n    cube <- .cube_filter_nonempty(cube)\n\n    # Finalize customizing cube class\n    .cube_set_class(cube, cube_class)\n}"

const rtdal006819Source0006 = `.reg_tile_convert.grd_cube <- function(cube, grid_system,
                                       roi = NULL, tiles = NULL) {
    # generate system grid tiles and intersects it with roi
    tiles_filtered <- .grid_filter_tiles(
        grid_system = grid_system, tiles = tiles, roi = roi
    )

    # prepare a sf object representing the bbox of each image in file_info
    # we perform a bind rows just to ensure that we never will lose a tile
    # and we can merge them because grd images are wgs84
    fi_bbox <-  suppressWarnings(
        .bbox_as_sf(.bbox(
            x = dplyr::bind_rows(cube[["file_info"]]),
            default_crs = .crs(cube),
            by_feature = TRUE
        ))
    )
    # create a new cube according to Sentinel-2 MGRS
    cube_class <- .cube_s3class(cube)
    cube <- tiles_filtered |>
        dplyr::rowwise() |>
        dplyr::group_map(~ {
            file_info <- .fi(cube)[.intersects({{ fi_bbox }}, .x), ]
            .cube_create(
                source = .tile_source(cube),
                collection = .tile_collection(cube),
                satellite = .tile_satellite(cube),
                sensor = .tile_sensor(cube),
                tile = .x[["tile_id"]],
                xmin = .xmin(.x),
                xmax = .xmax(.x),
                ymin = .ymin(.x),
                ymax = .ymax(.x),
                crs = .x[["crs"]],
                file_info = file_info
            )
        }) |>
        dplyr::bind_rows()

    # Filter non-empty file info
    cube <- .cube_filter_nonempty(cube)

    # Finalize customizing cube class
    cube_class <- c(cube_class[[1]], "sar_cube", cube_class[-1])
    .cube_set_class(cube, cube_class)
}`

const rtdal006819Source0007 = `.reg_tile_convert.rtc_cube <- function(cube,
                                       grid_system,
                                       roi = NULL,
                                       tiles = NULL) {
    # generate system grid tiles and intersects it with ROI
    tiles_filtered <- .grid_filter_tiles(
        grid_system = grid_system, tiles = tiles, roi = roi
    )
    # create a new cube according to Sentinel-2 MGRS
    cube_class <- .cube_s3class(cube)

    cube <- tiles_filtered |>
        dplyr::rowwise() |>
        dplyr::group_map(~ {
            # prepare a sf object representing the bbox of each image in
            # file_info
            cube_crs <- dplyr::filter(cube, .data[["crs"]] == .x[["crs"]])
            # check if it is required to use all tiles
            if (nrow(cube_crs) == 0) {
                # all tiles are used
                cube_crs <- cube
                # extracting files from all tiles
                cube_fi <- dplyr::bind_rows(cube_crs[["file_info"]])
            } else {
                # get cube files
                cube_fi <- .fi(cube_crs)
            }
            # extract bounding box from files
            fi_bbox <- suppressWarnings(
                .bbox_as_sf(.bbox(
                    x = cube_fi,
                    default_crs = cube_fi,
                    by_feature = TRUE
                ), as_crs = .x[["crs"]])
            )
            # check intersection between files and tile
            file_info <- cube_fi[.intersects({{ fi_bbox }}, .x), ]
            if (nrow(file_info) == 0) {
                return(NULL)
            }
            .cube_create(
                source = .tile_source(cube_crs),
                collection = .tile_collection(cube_crs),
                satellite = .tile_satellite(cube_crs),
                sensor = .tile_sensor(cube_crs),
                tile = .x[["tile_id"]],
                xmin = .xmin(.x),
                xmax = .xmax(.x),
                ymin = .ymin(.x),
                ymax = .ymax(.x),
                crs = .x[["crs"]],
                file_info = file_info
            )
        }) |>
        dplyr::bind_rows()

    # Filter non-empty file info
    cube <- .cube_filter_nonempty(cube)

    # Finalize customizing cube class
    cube_class <- c(cube_class[[1]], "sar_cube", cube_class[-1])
    .cube_set_class(cube, cube_class)
}`

