const rtdal006821Source0002 = `.request.httr2 <- function(req_obj, ...) {
    httr2::req_perform(req_obj, ...)
}`

const rtdal006821Source0003 = `.retry_request.httr2 <- function(url, n_tries = 10L, sleep = 10L, ...) {
    while (n_tries > 0L) {
        out <- .get_request(url = url, ...)
        if (!.response_is_error(out)) {
            return(out)
        }
        n_tries <- n_tries - 1L
        Sys.sleep(sleep)
    }
    return(out)
}`

const rtdal006821Source0004 = `.get_request.httr2 <- function(url, query = NULL, headers = NULL, ...,
                               quiet = TRUE) {
    req_obj <- httr2::request(url)
    # Prepare query
    req_obj <- .prepare_null(query, .request_query(req_obj, query), req_obj)
    # Prepare headers
    req_obj <- .prepare_null(
        headers, .request_headers(req_obj, headers), req_obj
    )
    # Quiet requisition? zero verbosity means quiet request
    quiet <- .prepare_lgl(quiet, 0L, 1L)
    # Perform request
    .request(req_obj, verbosity = quiet, ...)
}`

const rtdal006821Source0005 = `.request_query.httr2 <- function(req_obj, query) {
    # Force to a named list
    query <- as.list(query)
    # Append query into requisition
    httr2::req_url_query(req_obj, !!!query)
}`

const rtdal006821Source0006 = `.request_headers.httr2 <- function(req_obj, header) {
    # Force to a named list
    header <- as.list(header)
    # Create a default header
    default_value <- list(
        "User-Agent" = "SITS-R-PACKAGE (github.com/e-sensing/sits)",
        "Accept" = "*/*",
        "Connection" = "keep-alive"
    )

    header_values <- utils::modifyList(
        x = header,
        val = default_value
    )
    # Append headers into requisition
    httr2::req_headers(req_obj, !!!header_values)
}`

