const rtdal006822Source0001 = `.roi_sf_to_geojson <- function(roi) {
    # set caller to show in errors
    .check_set_caller(".roi_sf_to_geojson")
    # verifies if geojsonsf and jsonlite packages are installed
    .check_require_packages(c("geojsonsf", "jsonlite"))
    # pre-conditions
    .check_that(nrow(roi) == 1L)
    # reproject roi to WGS84
    .roi_as_sf(roi, as_crs = "WGS84") |>
        sf::st_convex_hull() |>
        sf::st_geometry() |>
        geojsonsf::sfc_geojson() |>
        jsonlite::fromJSON()
}`

const rtdal006822Source0005 = `.roi_type <- function(roi) {
    if (inherits(roi, c("sf", "sfc"))) {
        "sf"
    } else if (.has_bbox(roi)) {
        "bbox"
    } else if (all(.roi_lonlat_cols %in% names(roi))) {
        "lonlat"
    } else if (all(.roi_xs_cols %in% names(roi))) {
        "xs"
    } else if (inherits(roi, "SpatExtent")) {
        "xs"
    } else {
        stop(.conf("messages", ".roi_type"))
    }
}`

const rtdal006822Source0006 = `.roi_switch <- function(roi, ...) {
    switch(.roi_type(roi),
        ...
    )
}`

const rtdal006822Source0007 = ".roi_as_sf <- function(roi, default_crs = NULL, as_crs = NULL) {\n    # is the roi defined by a shapefile\n    if (is.character(roi) &&\n        file.exists(roi) &&\n        (tools::file_ext(roi) == \"shp\")) {\n        roi <- sf::st_read(roi)\n    }\n    # get roi type\n    roi_type <- .roi_type(roi)\n    # `xs` requires the definition of a CRS\n    if (roi_type == \"xs\") {\n        # check the default CRS\n        .check_that(.has(default_crs))\n    }\n    if (roi_type == \"xs\" || roi_type == \"bbox\") {\n        # transform roi to list\n        roi <- as.list(roi)\n    }\n    # convert R objects to sf object\n    roi <- .roi_switch(\n        roi = roi,\n        sf = roi,\n        bbox = .bbox_as_sf(.bbox(roi, default_crs = default_crs)),\n        lonlat = .bbox_as_sf(list(\n            xmin = roi[[\"lon_min\"]], xmax = roi[[\"lon_max\"]],\n            ymin = roi[[\"lat_min\"]], ymax = roi[[\"lat_max\"]],\n            crs = \"EPSG:4326\"\n        )),\n        xs = .bbox_as_sf(list(\n            xmin = roi[[\"xmin\"]], xmax = roi[[\"xmax\"]],\n            ymin = roi[[\"ymin\"]], ymax = roi[[\"ymax\"]],\n            crs = default_crs\n        ))\n    )\n    # Project roi\n    if (.has(as_crs)) {\n        roi <- sf::st_transform(roi, crs = as_crs)\n    }\n    # Clean roi\n    roi <- .sf_clean(roi)\n    # Transform feature to multipolygons\n    roi <- if (.has(nrow(roi)) && nrow(roi) > 1L) sf::st_union(roi) else roi\n    # Return roi\n    roi\n}"

const rtdal006822Source0008 = `.roi_write <- function(roi, output_file, quiet, ...) {
    sf::st_write(obj = roi, dsn = output_file, quiet = quiet, ...)
    output_file
}`

