const rtdal006833Source0001 = `.source_items_new.aws_cube <- function(source,
                                       collection,
                                       stac_query, ...,
                                       tiles = NULL,
                                       platform = NULL) {
    # check if platform is set
    if (!is.null(platform)) {
        platform <- .stac_format_platform(
            source = source,
            collection = collection,
            platform = platform
        )

        stac_query <- rstac::ext_query(
            q = stac_query,
            "platform" == platform
        )
    }

    # if specified, a filter per tile is added to the query
    if (!is.null(tiles)) {
        sep_tile <- paste0("MGRS-", tiles)

        stac_query <-
            rstac::ext_query(
                q = stac_query,
                "grid:code" %in% sep_tile
            )
    }

    # making the request
    items_info <- rstac::post_request(q = stac_query, ...)
    .check_stac_items(items_info)

    # if more than 2 times items pagination are found the progress bar
    # is displayed
    progress <- rstac::items_matched(items_info) > 2L *
        .conf("rstac_pagination_limit")
    # check documentation mode
    progress <- .message_progress(progress)
    # fetching all the metadata
    items_info <- rstac::items_fetch(
        items = items_info,
        progress = progress
    )

    return(items_info)
}`

const rtdal006833Source0002 = "`.source_items_new.aws_cube_landsat-c2-l2` <- function(source,\n                                                       collection,\n                                                       stac_query, ...,\n                                                       tiles = NULL,\n                                                       platform = NULL) {\n    if (!is.null(platform)) {\n        platform <- .stac_format_platform(\n            source = source,\n            collection = collection,\n            platform = platform\n        )\n\n        stac_query <- rstac::ext_query(\n            q = stac_query, \"platform\" == platform\n        )\n    }\n    # if specified, a filter per tile is added to the query\n    if (!is.null(tiles)) {\n        # format tile parameter provided by users\n        sep_tile <- .usgs_format_tiles(tiles)\n        # add filter by wrs path and row\n        stac_query <- rstac::ext_query(\n            q = stac_query,\n            \"landsat:wrs_path\" %in% sep_tile[[\"wrs_path\"]],\n            \"landsat:wrs_row\" %in% sep_tile[[\"wrs_row\"]]\n        )\n    }\n    # making the request based on ROI\n    items <- rstac::post_request(q = stac_query, ...)\n    .check_stac_items(items)\n    # fetching all the metadata and updating to upper case instruments\n    items <- suppressWarnings(\n        rstac::items_fetch(items = items, progress = FALSE)\n    )\n    return(items)\n}"

const rtdal006833Source0003 = "`.source_items_tile.aws_cube_landsat-c2-l2` <- function(source,\n                                                        items, ...,\n                                                        collection = NULL) {\n    # store tile info in items object\n    items[[\"features\"]] <- purrr::map(\n        items[[\"features\"]], function(feature) {\n            feature[[\"properties\"]][[\"tile\"]] <-\n                paste0(feature[[\"properties\"]][[\"landsat:wrs_path\"]],\n                    feature[[\"properties\"]][[\"landsat:wrs_row\"]],\n                    collapse = \"\"\n                )\n            feature\n        }\n    )\n    rstac::items_reap(items, field = c(\"properties\", \"tile\"))\n}"

const rtdal006833Source0004 = `.source_items_tile.aws_cube <- function(source,
                                        items, ...,
                                        collection = NULL) {
    # store tile info in items object
    items[["features"]] <- purrr::map(items[["features"]], function(feature) {
        feature[["properties"]][["tile"]] <-
            feature[["properties"]][["grid:code"]]
        feature[["properties"]][["tile"]] <-
            gsub("MGRS-", "", feature[["properties"]][["tile"]], fixed = TRUE)
        feature
    })

    rstac::items_reap(items, field = c("properties", "tile"))
}`

const rtdal006833Source0006 = `.source_configure_access.aws_cube <- function(source, collection) {
    .check_set_caller(".source_configure_access_aws_cube")
    if (.conf("sources", "AWS", "collections", collection, "open_data")
    == "false") {
        aws_access_key <- Sys.getenv("AWS_SECRET_ACCESS_KEY")
        if (.has_not(aws_access_key)) {
            stop(.conf("messages", ".source_configure_access_aws_cube"))
        }
    }
}`

