const rtdal006834Source0001 = ".source_item_get_hrefs.bdc_cube <- function(source, ...,\n                                            item,\n                                            collection = NULL) {\n    access_key <- Sys.getenv(\"BDC_ACCESS_KEY\")\n\n    href <- paste0(\n        unname(purrr::map_chr(item[[\"assets\"]], `[[`, \"href\")),\n        \"?access_token=\", access_key\n    )\n    # add gdal vsi in href urls\n    .stac_add_gdal_fs(href)\n}"

const rtdal006834Source0002 = `.source_items_new.bdc_cube <- function(source, ...,
                                       collection,
                                       stac_query,
                                       tiles = NULL,
                                       platform = NULL) {
    # if specified, a filter per tile is added to the query
    if (!is.null(tiles)) {
        stac_query <- rstac::ext_query(q = stac_query, "bdc:tile" %in% tiles)
    }
    # making the request
    items_info <- rstac::post_request(q = stac_query, ...)
    .check_stac_items(items_info)
    # if more than 2 times items pagination are found the progress bar
    # is displayed
    progress <- rstac::items_matched(items_info) >
        2L * .conf("rstac_pagination_limit")
    # check documentation mode
    progress <- .message_progress(progress)
    # fetching all the metadata
    rstac::items_fetch(
        items = items_info,
        progress = progress, ...
    )
}`

