const rtdal006837Source0001 = `.source_items_new.deafrica_cube <- function(source, ...,
                                            collection,
                                            stac_query,
                                            tiles = NULL,
                                            platform = NULL) {
    .check_that(is.null(tiles))
    # Convert roi to bbox
    roi <- .stac_intersects_as_bbox(stac_query)
    stac_query[["params"]][["intersects"]] <- NULL
    stac_query[["params"]][["bbox"]] <- roi$bbox
    # making the request
    items_info <- rstac::post_request(q = stac_query, ...)
    .check_stac_items(items_info)
    # if more than 2 times items pagination are found the progress bar
    # is displayed
    progress <- rstac::items_matched(items_info) >
        2L * .conf("rstac_pagination_limit")
    # check documentation mode
    progress <- .message_progress(progress)
    # fetching all the metadata and updating to upper case instruments
    items_info <- rstac::items_fetch(items = items_info, progress = progress)
    # checks if the items returned any items
    .check_stac_items(items_info)
    return(items_info)
}`

const rtdal006837Source0002 = "`.source_items_new.deafrica_cube_sentinel-2-l2a` <- function(source, ...,\n                                                             collection,\n                                                             stac_query,\n                                                             tiles = NULL,\n                                                             platform = NULL) {\n    # set caller to show in errors\n    .check_set_caller(\".source_items_new\")\n    # check platform\n    if (!is.null(platform)) {\n        platform <- .stac_format_platform(\n            source = source,\n            collection = collection,\n            platform = platform\n        )\n    }\n    # check spatial extensions\n    if (!is.null(tiles)) {\n        roi <- .s2_mgrs_to_roi(tiles)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- c(\n            roi[[\"lon_min\"]],\n            roi[[\"lat_min\"]],\n            roi[[\"lon_max\"]],\n            roi[[\"lat_max\"]]\n        )\n    } else {\n        roi <- .stac_intersects_as_bbox(stac_query)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- roi$bbox\n    }\n    # make request\n    items_info <- rstac::post_request(q = stac_query, ...)\n    items_info <- rstac::items_fetch(items = items_info, progress = FALSE)\n    # filter items\n    items_info <- rstac::items_filter(items_info,\n        filter_fn = function(feature) {\n            lgl_res <- TRUE\n\n            if (!is.null(platform)) {\n                lgl_res <- feature[[\"properties\"]][[\"platform\"]] == platform\n            }\n\n            lgl_res\n        }\n    )\n    # check results\n    .check_stac_items(items_info)\n    # done\n    items_info\n}"

const rtdal006837Source0003 = "`.source_items_new.deafrica_cube_sentinel-1-rtc` <- function(source, ...,\n                                                             collection,\n                                                             stac_query,\n                                                             tiles = NULL,\n                                                             platform = NULL,\n                                                             orbit = NULL) {\n    # set caller to show in errors\n    .check_set_caller(\".source_items_new\")\n    # check orbits\n    orbits <- .conf(\"sources\", source, \"collections\", collection, \"orbits\")\n    .check_chr_within(orbit, orbits)\n    # check platform\n    if (!is.null(platform)) {\n        platform <- .stac_format_platform(\n            source = source,\n            collection = collection,\n            platform = platform\n        )\n    }\n    # check spatial extensions\n    if (!is.null(tiles)) {\n        roi <- .s2_mgrs_to_roi(tiles)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- c(\n            roi[[\"lon_min\"]],\n            roi[[\"lat_min\"]],\n            roi[[\"lon_max\"]],\n            roi[[\"lat_max\"]]\n        )\n    } else {\n        roi <- .stac_intersects_as_bbox(stac_query)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- roi$bbox\n    }\n    # make request\n    items_info <- rstac::post_request(q = stac_query, ...)\n    items_info <- rstac::items_fetch(items = items_info, progress = FALSE)\n    # filter items\n    items_info <- rstac::items_filter(items_info,\n        filter_fn = function(feature) {\n            lgl_res <- feature[[\"properties\"]][[\"sat:orbit_state\"]] == orbit &&\n                feature[[\"properties\"]][[\"sar:instrument_mode\"]] == \"IW\" &&\n                feature[[\"properties\"]][[\"sar:frequency_band\"]] == \"C\"\n\n            if (!is.null(platform)) {\n                lgl_res <- lgl_res &&\n                    feature[[\"properties\"]][[\"platform\"]] == platform\n            }\n\n            lgl_res\n        }\n    )\n    # check results\n    .check_stac_items(items_info)\n    # done\n    items_info\n}"

