const rtdal006841Source0001 = `.source_collection_access_test.mpc_cube <- function(source,
                                                    collection,
                                                    bands, ...,
                                                    start_date = NULL,
                                                    end_date = NULL,
                                                    dry_run = TRUE) {
    # require package
    .check_require_packages("rstac")

    items_query <- .stac_create_items_query(
        source = source,
        collection = collection,
        start_date = start_date,
        end_date = end_date,
        limit = 1L
    )
    # assert that service is online
    items <- .try(
        {
            rstac::post_request(items_query, ...)
        },
        .default = NULL
    )
    .check_stac_items(items)
    # signing the url with the mpc token
    access_key <- Sys.getenv("MPC_TOKEN")
    if (!nzchar(access_key)) {
        access_key <- NULL
    }
    items <- suppressWarnings(
        rstac::items_sign(
            items,
            sign_fn = rstac::sign_planetary_computer(
                headers = c("Ocp-Apim-Subscription-Key" = access_key)
            )
        )
    )
    items <- .source_items_bands_select(
        source = source,
        items = items,
        bands = bands[[1L]],
        collection = collection, ...
    )
    href <- .source_item_get_hrefs(
        source = source,
        item = items[["features"]][[1L]],
        collection = collection, ...
    )
    # assert that token and/or href is valid
    if (dry_run) {
        rast <- .try(
            {
                .raster_open_rast(href)
            },
            default = NULL
        )
        .check_null_parameter(rast)
    }
    return(invisible(source))
}`

const rtdal006841Source0002 = "`.source_collection_access_test.mpc_cube_sentinel-1-grd` <- function(source,\n                                                                     collection,\n                                                                     bands, ...,\n                                                                     orbit = \"descending\",\n                                                                     start_date = NULL,\n                                                                     end_date = NULL,\n                                                                     dry_run = TRUE) {\n    # require package\n    .check_require_packages(\"rstac\")\n    orbits <- .conf(\"sources\", source, \"collections\", collection, \"orbits\")\n    .check_chr_within(x = orbit, within = orbits)\n\n    stac_query <- .stac_create_items_query(\n        source = source,\n        collection = collection,\n        start_date = start_date,\n        end_date = end_date,\n        limit = 1L\n    )\n    stac_query <- rstac::ext_filter(\n        stac_query,\n        `sar:frequency_band` == \"C\" &&\n            `sar:instrument_mode` == \"IW\" &&\n            `sat:orbit_state` == {{ orbit }}\n    )\n\n    # assert that service is online\n    items <- .try(\n        {\n            rstac::post_request(stac_query, ...)\n        },\n        .default = NULL\n    )\n    .check_stac_items(items)\n\n    # signing the url with the mpc token\n    access_key <- Sys.getenv(\"MPC_TOKEN\")\n    if (!nzchar(access_key)) {\n        access_key <- NULL\n    }\n    items <- suppressWarnings(\n        rstac::items_sign(\n            items,\n            sign_fn = rstac::sign_planetary_computer(\n                headers = c(\"Ocp-Apim-Subscription-Key\" = access_key)\n            )\n        )\n    )\n    items <- .source_items_bands_select(\n        source = source,\n        items = items,\n        bands = bands[[1L]],\n        collection = collection, ...\n    )\n    href <- .source_item_get_hrefs(\n        source = source,\n        item = items[[\"features\"]][[1L]],\n        collection = collection, ...\n    )\n    # assert that token and/or href is valid\n    if (dry_run) {\n        rast <- .try(\n            {\n                .raster_open_rast(href)\n            },\n            default = NULL\n        )\n        .check_null_parameter(rast)\n    }\n    return(invisible(NULL))\n}"

const rtdal006841Source0003 = "`.source_collection_access_test.mpc_cube_sentinel-1-rtc` <- function(source,\n                                                                     collection,\n                                                                     bands, ...,\n                                                                     orbit = \"descending\",\n                                                                     start_date = NULL,\n                                                                     end_date = NULL,\n                                                                     dry_run = TRUE) {\n    `.source_collection_access_test.mpc_cube_sentinel-1-grd`(\n        source = source,\n        collection = collection,\n        bands = bands, ...,\n        orbit = orbit,\n        start_date = start_date,\n        end_date = end_date,\n        dry_run = dry_run\n    )\n}"

const rtdal006841Source0004 = "`.source_tile_get_bbox.mpc_cube_sentinel-1-grd` <- function(source,\n                                                            file_info, ...,\n                                                            collection = NULL) {\n    .check_set_caller(\".source_tile_get_bbox_mpc_s1_grd\")\n\n    # pre-condition\n    .check_num(nrow(file_info), min = 1L)\n\n    # get bbox based on file_info\n    xmin <- min(file_info[[\"xmin\"]])\n    ymin <- min(file_info[[\"ymin\"]])\n    xmax <- max(file_info[[\"xmax\"]])\n    ymax <- max(file_info[[\"ymax\"]])\n\n    # post-condition\n    .check_that(xmin < xmax && ymin < ymax)\n    # create a bbox\n    bbox <- c(xmin = xmin, ymin = ymin, xmax = xmax, ymax = ymax)\n    return(bbox)\n}"

