const rtdal006841Source0007 = "`.source_items_new.mpc_cube_sentinel-1-grd` <- function(source,\n                                                        collection,\n                                                        stac_query, ...,\n                                                        tiles = NULL,\n                                                        orbit = \"descending\") {\n    .check_set_caller(\".source_items_new_mpc_s1_grd\")\n\n    orbits <- .conf(\"sources\", source, \"collections\", collection, \"orbits\")\n    .check_chr_within(\n        orbit,\n        within = orbits\n    )\n\n    stac_query <- rstac::ext_filter(\n        stac_query,\n        `sar:frequency_band` == \"C\" &&\n            `sar:instrument_mode` == \"IW\" &&\n            `sat:orbit_state` == {{ orbit }}\n    )\n\n    # Sentinel-1 does not support tiles - convert to ROI\n    if (!is.null(tiles)) {\n        roi <- .s2_mgrs_to_roi(tiles)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- c(\n            roi[[\"lon_min\"]],\n            roi[[\"lat_min\"]],\n            roi[[\"lon_max\"]],\n            roi[[\"lat_max\"]]\n        )\n    }\n    items_info <- rstac::post_request(q = stac_query, ...)\n    .check_stac_items(items_info)\n    # fetching all the metadata\n    items_info <- suppressWarnings(\n        rstac::items_fetch(items = items_info, progress = FALSE)\n    )\n\n    # assign href\n    access_key <- Sys.getenv(\"MPC_TOKEN\")\n    if (!nzchar(access_key)) {\n        access_key <- NULL\n    }\n    # Clean old tokens cached in rstac\n    .mpc_clean_token_cache()\n    items_info <- suppressWarnings(\n        rstac::items_sign(\n            items_info,\n            sign_fn = rstac::sign_planetary_computer(\n                headers = c(\"Ocp-Apim-Subscription-Key\" = access_key)\n            )\n        )\n    )\n    return(items_info)\n}"

const rtdal006841Source0008 = "`.source_items_new.mpc_cube_sentinel-1-rtc` <- function(source,\n                                                        collection,\n                                                        stac_query, ...,\n                                                        tiles = NULL,\n                                                        orbit = \"descending\") {\n    `.source_items_new.mpc_cube_sentinel-1-grd`(\n        source = source,\n        collection = collection,\n        stac_query = stac_query, ...,\n        tiles = tiles,\n        orbit = orbit\n    )\n}"

const rtdal006841Source0009 = "`.source_items_new.mpc_cube_sentinel-2-l2a` <- function(source,\n                                                        collection,\n                                                        stac_query, ...,\n                                                        tiles = NULL,\n                                                        platform = NULL) {\n    if (!is.null(platform)) {\n        platform <- .stac_format_platform(\n            source = source,\n            collection = collection,\n            platform = platform\n        )\n        stac_query <- rstac::ext_query(\n            q = stac_query, \"platform\" == platform\n        )\n    }\n    # mpc does not support %in% operator\n    if (!is.null(tiles)) {\n        items_list <- lapply(tiles, function(tile) {\n            stac_query <- rstac::ext_query(\n                q = stac_query, \"s2:mgrs_tile\" == tile\n            )\n            # making the request\n            items_info <- rstac::post_request(q = stac_query, ...)\n            .check_stac_items(items_info)\n            # fetching all the metadata\n            suppressWarnings(\n                rstac::items_fetch(items = items_info, progress = FALSE)\n            )\n        })\n\n        # getting the first item info\n        items_info <- items_list[[1L]]\n        # joining the items\n        items_info[[\"features\"]] <- do.call(\n            c,\n            args = lapply(items_list, `[[`, \"features\")\n        )\n    } else {\n        items_info <- rstac::post_request(q = stac_query, ...)\n        .check_stac_items(items_info)\n        # fetching all the metadata\n        items_info <- suppressWarnings(\n            rstac::items_fetch(items = items_info, progress = FALSE)\n        )\n    }\n\n    # assign href\n    access_key <- Sys.getenv(\"MPC_TOKEN\")\n    if (!nzchar(access_key)) {\n        access_key <- NULL\n    }\n    # Clean old tokens cached in rstac\n    .mpc_clean_token_cache()\n    items_info <- suppressWarnings(\n        rstac::items_sign(\n            items_info,\n            sign_fn = rstac::sign_planetary_computer(\n                headers = c(\"Ocp-Apim-Subscription-Key\" = access_key)\n            )\n        )\n    )\n    return(items_info)\n}"

const rtdal006841Source0010 = "`.source_items_new.mpc_cube_landsat-c2-l2` <- function(source,\n                                                       collection,\n                                                       stac_query, ...,\n                                                       tiles = NULL,\n                                                       platform = NULL) {\n    .check_set_caller(\".source_items_new_mpc_cube_landsat_c2_l2\")\n    .check_that(is.null(tiles))\n    if (.has(platform)) {\n        platform <- .stac_format_platform(\n            source = source,\n            collection = collection,\n            platform = platform\n        )\n        stac_query <- rstac::ext_query(\n            q = stac_query, \"platform\" == platform\n        )\n    }\n    # making the request based on ROI\n    items <- rstac::post_request(q = stac_query, ...)\n    .check_stac_items(items)\n    # fetching all the metadata and updating to upper case instruments\n    items <- suppressWarnings(\n        rstac::items_fetch(items = items, progress = FALSE)\n    )\n    # assign href\n    access_key <- Sys.getenv(\"MPC_TOKEN\")\n    if (!nzchar(access_key)) {\n        access_key <- NULL\n    }\n    # Clean old tokens cached in rstac\n    .mpc_clean_token_cache()\n    items <- suppressWarnings(\n        rstac::items_sign(\n            items,\n            sign_fn = rstac::sign_planetary_computer(\n                headers = c(\"Ocp-Apim-Subscription-Key\" = access_key)\n            )\n        )\n    )\n    return(items)\n}"

const rtdal006841Source0011 = `.source_items_new.mpc_cube <- function(source,
                                       collection,
                                       stac_query, ...,
                                       tiles = NULL,
                                       platform = NULL) {
    .check_set_caller(".source_items_new_mpc_cube")
    .check_that(is.null(tiles))
    if (.has(platform)) {
        platform <- .stac_format_platform(
            source = source,
            collection = collection,
            platform = platform
        )
        stac_query <- rstac::ext_query(
            q = stac_query, "platform" == platform
        )
    }
    # making the request based on ROI
    items <- rstac::post_request(q = stac_query, ...)
    .check_stac_items(items)
    # fetching all the metadata and updating to upper case instruments
    items <- suppressWarnings(
        rstac::items_fetch(items = items, progress = FALSE)
    )
    # assign href
    access_key <- Sys.getenv("MPC_TOKEN")
    if (!nzchar(access_key)) {
        access_key <- NULL
    }
    # Clean old tokens cached in rstac
    .mpc_clean_token_cache()
    items <- suppressWarnings(
        rstac::items_sign(
            items,
            sign_fn = rstac::sign_planetary_computer(
                headers = c("Ocp-Apim-Subscription-Key" = access_key)
            )
        )
    )
    return(items)
}`

const rtdal006841Source0012 = "`.source_items_new.mpc_cube_cop-dem-glo-30` <- function(source,\n                                                        collection,\n                                                        stac_query, ...,\n                                                        tiles = NULL) {\n    .check_set_caller(\".source_items_new_mpc_cube_cop-dem-glo-30\")\n\n    # COP-DEM-GLO-30 does not support tiles - convert to ROI\n    if (!is.null(tiles)) {\n        roi <- .s2_mgrs_to_roi(tiles)\n        stac_query[[\"params\"]][[\"intersects\"]] <- NULL\n        stac_query[[\"params\"]][[\"bbox\"]] <- c(\n            roi[[\"lon_min\"]],\n            roi[[\"lat_min\"]],\n            roi[[\"lon_max\"]],\n            roi[[\"lat_max\"]]\n        )\n    }\n\n    # Fix temporal interval (All data available in the same date)\n    stac_query[[\"params\"]][[\"datetime\"]] <- \"2021-04-21/2021-04-23\"\n\n    # Search content\n    items_info <- rstac::post_request(q = stac_query, ...)\n    .check_stac_items(items_info)\n    # fetching all the metadata\n    items_info <- suppressWarnings(\n        rstac::items_fetch(items = items_info, progress = FALSE)\n    )\n\n    # assign href\n    access_key <- Sys.getenv(\"MPC_TOKEN\")\n    if (!nzchar(access_key)) {\n        access_key <- NULL\n    }\n    # Clean old tokens cached in rstac\n    .mpc_clean_token_cache()\n    items_info <- suppressWarnings(\n        rstac::items_sign(\n            items_info,\n            sign_fn = rstac::sign_planetary_computer(\n                headers = c(\"Ocp-Apim-Subscription-Key\" = access_key)\n            )\n        )\n    )\n    return(items_info)\n}"

const rtdal006841Source0013 = `.source_items_new.mpc_cube_hlss30 <- function(source,
                                              collection,
                                              stac_query, ...,
                                              tiles = NULL) {
    .check_set_caller(".source_items_new_mpc_cube_hls")

    # HLSS30/HLSL30 does not support tiles - convert to ROI
    if (!is.null(tiles)) {
        roi <- .s2_mgrs_to_roi(tiles)
        stac_query[["params"]][["intersects"]] <- NULL
        stac_query[["params"]][["bbox"]] <- c(
            roi[["lon_min"]],
            roi[["lat_min"]],
            roi[["lon_max"]],
            roi[["lat_max"]]
        )
    }
    # Search content
    items_info <- rstac::post_request(q = stac_query, ...)
    .check_stac_items(items_info)
    # fetching all the metadata
    items_info <- suppressWarnings(
        rstac::items_fetch(items = items_info, progress = FALSE)
    )
    # assign href
    access_key <- Sys.getenv("MPC_TOKEN")
    if (!nzchar(access_key)) {
        access_key <- NULL
    }
    # Clean old tokens cached in rstac
    .mpc_clean_token_cache()
    items_info <- suppressWarnings(
        rstac::items_sign(
            items_info,
            sign_fn = rstac::sign_planetary_computer(
                headers = c("Ocp-Apim-Subscription-Key" = access_key)
            )
        )
    )
    return(items_info)
}`

