const rtdal006842Source0001 = `.source_collection_access_test.ogh_cube <- function(source, collection,
                                                     bands, ...,
                                                     start_date = NULL,
                                                     end_date = NULL,
                                                     dry_run = FALSE) {
    # require package
    .check_require_packages("rstac")
    # query items
    items <- .try(
        {
            .stac_static_items_query(
                source = source,
                collection = collection,
                start_date = start_date,
                end_date = end_date,
                limit = 1
            )
        },
        .default = NULL
    )
    # check items
    .check_stac_items(items)
    # select bands
    items <- .source_items_bands_select(
        source = source,
        items = items,
        bands = bands[[1L]],
        collection = collection, ...
    )
    # get hrefs available
    href <- .source_item_get_hrefs(
        source = source,
        item = items[["features"]][[1L]],
        collection = collection, ...
    )
    # assert that token and/or href is valid
    if (dry_run) {
        rast <- .try(
            {
                .raster_open_rast(href)
            },
            default = NULL
        )
        .check_null_parameter(rast)
    }
    return(invisible(source))
}`

const rtdal006842Source0002 = ".source_items_new.ogh_cube <- function(source,\n                                       collection,\n                                       stac_query, ...,\n                                       tiles = NULL,\n                                       platform = NULL) {\n    .check_set_caller(\".source_items_new_ogh_cube\")\n    # transform ``datetime`` to ``start_date`` and ``end_date``\n    datetime <- stac_query[[\"params\"]][[\"datetime\"]]\n    datetime <- stringr::str_split(datetime, \"/\")\n    datetime <- datetime[[1]]\n    # get ``start_date`` and ``end_date``\n    start_date <- datetime[[1]]\n    end_date <- datetime[[2]]\n    # read static items from ogh\n    items <- .try(\n        {\n            .stac_static_items_query(\n                source = source,\n                collection = collection,\n                start_date = start_date,\n                end_date = end_date\n            )\n        },\n        .default = NULL\n    )\n    # check results\n    .check_stac_items(items)\n    # return\n    return(items)\n}"

