const rtdal006848Source0001 = `.stac_select_bands <- function(items, bands_source, bands_sits) {
    .check_set_caller(".stac_select_bands")
    # verify if the mapped band in on item assets
    .check_chr_within(
        x = bands_source,
        within = rstac::items_fields(items, "assets"),
        case_sensitive = FALSE
    )
    # covert bands to sits names
    bands_source <- toupper(bands_source)
    bands_converter <- toupper(bands_sits)
    names(bands_converter) <- bands_source

    # organize the items
    items[["features"]] <- purrr::map(items[["features"]], function(item) {
        names(item[["assets"]]) <- toupper(names(item[["assets"]]))
        item[["assets"]] <- item[["assets"]][bands_source]
        names(item[["assets"]]) <- unname(bands_converter[names(item[["assets"]])])
        item
    })
    items
}`

const rtdal006848Source0005 = `.stac_create_items_query <- function(source,
                                     collection,
                                     ...,
                                     roi = NULL,
                                     start_date = NULL,
                                     end_date = NULL,
                                     limit = NULL) {
    # get collection original name
    collection <- .source_collection_name(source = source, collection = collection)
    # get the URL
    url <- .source_url(source = source)
    # obtain the datetime parameter for STAC like parameter
    datetime <- .stac_format_datetime(start_date, end_date)
    # by default, roi is NULL
    roi_geojson <- NULL
    # obtain the bounding box and intersects parameters
    if (.has(roi)) {
        # convert to geojson
        roi_geojson <- .roi_sf_to_geojson(roi)
    }
    # get the limit items to be returned in each page
    if (is.null(limit)) {
        limit <- .conf("rstac_pagination_limit")
    }
    # create a query object to be searched by STAC
    rstac_query <- rstac::stac_search(
        q = rstac::stac(url),
        collections = collection,
        bbox = NULL,
        intersects = roi_geojson,
        datetime = datetime,
        limit = limit
    )
    # adjust limit datatype
    rstac_query[["params"]][["limit"]] <- as.numeric(limit)
    # return!
    rstac_query
}`

const rtdal006848Source0007 = `.stac_datetime_as_dates <- function(stac_query) {
    query_datetime <- stringr::str_split(stac_query[["params"]][["datetime"]], "/")
    list(start_date = query_datetime[[1L]][1L], end_date = query_datetime[[1L]][2L])
}`

const rtdal006848Source0010 = ".stac_static_link_filter.ogh <- function(source, collection, href,\n                                         start_date, end_date) {\n    # extract date interval\n    interval <- gsub(\"^.*([0-9]{8}_[0-9]{8})\\\\.json$\", \"\\\\1\", href)\n\n    # transform date interval in date\n    date <- as.Date(strsplit(interval, \"_\")[[1]][[1]], format = \"%Y%m%d\")\n\n    # validate if ``start_date`` and ``end_date`` are in the interval\n    is_in_interval <- (is.null(start_date) || date >= start_date) &&\n        (is.null(end_date) || date < end_date)\n}"

const rtdal006848Source0012 = `.stac_static_items_query <- function(source,
                                     collection,
                                     ...,
                                     roi = NULL,
                                     start_date = NULL,
                                     end_date = NULL,
                                     limit = NULL) {
    # get collection original name
    collection <- .source_collection_name(source = source, collection = collection)
    # get the URL
    url <- .source_url(source = source)
    # get the limit items to be returned in each page
    if (is.null(limit)) {
        limit <- .conf("rstac_pagination_limit")
    }
    # read stac
    stac_obj <- rstac::read_stac(url)
    # get items links
    items_links <- rstac::links(stac_obj)
    # prepare source to define items filter
    source_name <- source
    class(source_name) <- tolower(source)
    # filter links
    items_links <- purrr::map_lgl(items_links, function(link) {
        # check if link is from an item
        is_item <- link[["rel"]] == "item"
        # apply general static filter
        is_selected <- .stac_static_link_filter(
            source = source_name,
            collection = collection,
            href = link[["href"]],
            start_date = start_date,
            end_date = end_date
        )
        # return
        is_item && is_selected
    })
    # update stac object with selected links
    stac_obj[["links"]] <- stac_obj[["links"]][items_links]
    # read links
    rstac::read_items(stac_obj, limit = limit, progress = FALSE)
}`

