const rtdal006853Source0127 = `.tile_eo_from_files <- function(files, fid, bands, date, base_tile,
                                update_bbox) {
    base_tile <- .tile(base_tile)
    if (update_bbox) {
        # Open raster
        rast <- .raster_open_rast(files)
        # Update spatial bbox
        .xmin(base_tile) <- .raster_xmin(rast)
        .xmax(base_tile) <- .raster_xmax(rast)
        .ymin(base_tile) <- .raster_ymin(rast)
        .ymax(base_tile) <- .raster_ymax(rast)
        .crs(base_tile) <- .raster_crs(rast)
    }
    # Update file_info
    .fi(base_tile) <- .fi_eo_from_files(
        files = files, fid = fid, bands = bands, date = date
    )
    # Return eo tile
    base_tile
}`

const rtdal006853Source0129 = `.tile_derived_from_file <- function(file, band, base_tile, derived_class,
                                    labels = NULL, update_bbox = FALSE) {
    # set caller to show in errors
    .check_set_caller(".tile_derived_from_file")
    if (derived_class %in% c("probs_cube", "variance_cube")) {
        # Open first block file to be merged
        rast <- .raster_open_rast(file)
        # Check number of labels is correct
        .check_that(.raster_nlayers(rast) == length(labels))
    }

    base_tile <- .tile(base_tile)
    if (update_bbox) {
        # Open raster
        rast <- .raster_open_rast(file)
        # Update spatial bbox
        .xmin(base_tile) <- .raster_xmin(rast)
        .xmax(base_tile) <- .raster_xmax(rast)
        .ymin(base_tile) <- .raster_ymin(rast)
        .ymax(base_tile) <- .raster_ymax(rast)
        .crs(base_tile) <- .raster_crs(rast)
    }
    # Update labels before file_info
    .tile_labels(base_tile) <- labels
    # Update file_info
    .fi(base_tile) <- .fi_derived_from_file(
        file = file,
        band = band,
        start_date = .tile_start_date(base_tile),
        end_date = .tile_end_date(base_tile)
    )
    # Set tile class and return tile
    .cube_set_class(base_tile, .conf_derived_s3class(derived_class))
}`

const rtdal006853Source0130 = `.tile_segments_from_file <- function(file, band, base_tile, vector_class,
                                     labels = NULL, update_bbox = FALSE) {
    v_obj <- .vector_read_vec(file_path = file)
    base_tile <- .tile(base_tile)
    bbox <- .vector_bbox(v_obj)
    if (update_bbox) {
        # Update spatial bbox
        .xmin(base_tile) <- bbox[["xmin"]]
        .xmax(base_tile) <- bbox[["xmax"]]
        .ymin(base_tile) <- bbox[["ymin"]]
        .ymax(base_tile) <- bbox[["ymax"]]
        .crs(base_tile) <- .vector_crs(v_obj, wkt = TRUE)
    }
    # Update labels before file_info
    .tile_labels(base_tile) <- labels
    # Update file_info
    .vi(base_tile) <- .vi_segment_from_file(
        file = file,
        base_tile = base_tile,
        band = band,
        start_date = .tile_start_date(base_tile),
        end_date = .tile_end_date(base_tile)
    )
    # Set tile class and return tile
    seg_classes <- c(.conf_vector_s3class(vector_class), class(base_tile))
    .cube_set_class(base_tile, seg_classes)
}`

const rtdal006853Source0131 = `.tile_derived_merge_blocks <- function(file, band, labels, base_tile,
                                       derived_class, block_files, multicores,
                                       update_bbox = FALSE) {
    # set caller to show in errors
    .check_set_caller(".tile_derived_merge_blocks")
    if (derived_class %in% c("probs_cube", "variance_cube")) {
        # Open first block file to be merged
        rast <- .raster_open_rast(unlist(block_files)[[1L]])
        # Check number of labels is correct
        .check_that(.raster_nlayers(rast) == length(labels))
    }
    base_tile <- .tile(base_tile)
    # Get conf band
    band_conf <- .conf_derived_band(
        derived_class = derived_class,
        band = band
    )
    # Set base tile
    base_file <- if (update_bbox) NULL else .tile_path(base_tile)
    # Create a template raster based on the first image of the tile
    .raster_merge_blocks(
        out_files = file,
        base_file = base_file,
        block_files = block_files,
        data_type = .data_type(band_conf),
        missing_value = .miss_value(band_conf),
        multicores = multicores
    )
    # Create tile based on template
    tile <- .tile_derived_from_file(
        file = file,
        band = band,
        base_tile = base_tile,
        derived_class = derived_class,
        labels = labels,
        update_bbox = update_bbox
    )
    # If all goes well, delete block files
    unlink(block_files)
    # Return derived tile
    tile
}`

const rtdal006853Source0134 = `.tile_area_freq.class_cube <- function(tile) {
    # get tile crs
    tile_crs <- sf::st_crs(.tile_crs(tile))
    # get tile crs unit (metre or degree)
    tile_crs_unit <- tile_crs$units_gdal
    # validate if crs is equal area
    tile_crs_equal_area <- .crs_is_equal_area(tile_crs)
    # extract the file path
    tile_file <- .tile_paths(tile)
    # read the files with terra
    rast <- .raster_open_rast(tile_file)
    # get area by pixels
    if (!tile_crs_equal_area && tile_crs_unit == "metre") {
        # get a frequency of values
        class_areas <- .raster_freq(rast) |>
            dplyr::select(-dplyr::all_of("layer"))
        # transform to km^2
        cell_size <- .tile_xres(tile) * .tile_yres(tile)
        class_areas[["area"]] <- (class_areas[["count"]] * cell_size) / 1000000L
    } else {
        # get pixels by class
        class_count <- .raster_freq(rast)
        # get area by class in km^2
        class_areas <- .raster_area(rast = rast, unit = "km", byValue = TRUE)
        # Merge area and pixel count
        class_areas <- dplyr::full_join(class_count, class_areas, by = "value") |>
            dplyr::select(-dplyr::all_of(c("layer.x", "layer.y")))
    }
    # change value to character
    class_areas <- dplyr::mutate(
        class_areas,
        value = as.character(.data[["value"]])
    )
    # create a data.frame with the labels
    tile_labels <- .tile_labels(tile)
    df1 <- tibble::tibble(
        value = names(tile_labels),
        class = unname(tile_labels)
    )
    # join the labels with the areas
    sum_areas <- dplyr::full_join(df1, class_areas, by = "value")
    sum_areas <- dplyr::mutate(sum_areas,
                               area = signif(.data[["area"]], 2L),
                               .keep = "unused"
    )
    # replace na
    sum_clean <- sum_areas |>
        tidyr::replace_na(list(count = 0L, area = 0.0))

    sum_clean
}`

const rtdal006853Source0135 = `.tile_area_freq.class_vector_cube <- function(tile) {
    # Open segments
    segments <- .segments_read_vec(tile)
    segments[["area"]] <- sf::st_area(segments)
    segments <- sf::st_drop_geometry(segments)
    segments <- units::drop_units(segments)
    # Retrieve the area
    freq <- segments |>
        dplyr::group_by(class) |>
        dplyr::summarise(area = sum(.data[["area"]])) |>
        dplyr::select(c(dplyr::all_of("area"), dplyr::all_of("class")))
    # Return frequencies
    freq
}`

const rtdal006853Source0137 = `.tile_area_freq.default <- function(tile) {
    tile <- tibble::as_tibble(tile)
    tile <- .cube_find_class(tile)
    tile <- .tile_area_freq(tile)
    tile
}`

const rtdal006853Source0140 = `.tile_extract_segments <- function(tile, band, chunk) {
    tile <- .tile(tile)
    fi <- .fi(tile)
    fi <- .fi_filter_bands(fi = fi, bands = band)
    files <- .fi_paths(fi)
    # Create a SpatRaster object
    rast <- .raster_open_rast(files)
    names(rast) <- paste0(band, "-", seq_len(.raster_nlayers(rast)))
    # Read the segments
    segments <- .vector_read_vec(chunk[["segments"]][[1L]])
    # Extract the values
    values <- exactextractr::exact_extract(
        x = rast,
        y = segments,
        fun = NULL,
        include_cols = "pol_id"
    )
    values <- dplyr::bind_rows(values)
    values <- dplyr::select(values, -"coverage_fraction")
    # Return values
    as.matrix(values)
}`

const rtdal006853Source0144 = `.tile_classif_end <- function(tile, start_time, verbose) {
    end_time <- Sys.time()
    if (verbose) {
        message("Tile '", tile[["tile"]], "' finished at ", end_time)
        message(
            "Elapsed time of ",
            format(round(end_time - start_time, digits = 2L))
        )
        message("")
    }
}`

const rtdal006853Source0145 = `.tile_overview_size <- function(tile, max_size) {
    # check if the tile is a COG file
    cog_sizes <- .tile_cog_sizes(tile)
    if (.has(cog_sizes)) {
        # find out the first cog size smaller than max_size
        i <- 1L
        while (i < length(cog_sizes)) {
            if (cog_sizes[[i]][["xsize"]] < max_size ||
                cog_sizes[[i]][["ysize"]] < max_size) {
                break
            }
            i <- i + 1L
        }
        # determine the best COG size
        best_cog_size <- cog_sizes[[i]]
        c(
            xsize = best_cog_size[["xsize"]],
            ysize = best_cog_size[["ysize"]]
        )
    } else {
        # get the maximum number of bytes for the tiles
        nrows_tile <- max(.tile_nrows(tile))
        ncols_tile <- max(.tile_ncols(tile))
        # get the ratio to the max plot size
        ratio_x <- max(ncols_tile / max_size, 1L)
        ratio_y <- max(nrows_tile / max_size, 1L)
        # if image is smaller than 1000 x 1000, return full size
        if (ratio_x == 1L && ratio_y == 1L) {
            return(c(
                xsize = ncols_tile,
                ysize = nrows_tile
            ))
        }
        # if ratio is greater than 1, get the maximum
        ratio <- max(ratio_x, ratio_y)
        # calculate nrows, ncols to be plotted
        c(
            xsize = floor(ncols_tile / ratio),
            ysize = floor(nrows_tile / ratio)
        )
    }
}`

const rtdal006853Source0146 = `.tile_cog_sizes <- function(tile) {
    # run gdalinfo on file
    info <- utils::capture.output(sf::gdal_utils(
        source = .tile_path(tile),
        destination = NULL
    ))
    info2 <- stringr::str_split(info, pattern = "\n")
    # capture the line containg overview info
    over <- unlist(info2[grepl("Overview", info2)])
    over <- over[!grepl("arbitrary", over)]
    if (!.has(over)) {
        return(NULL)
    }
    # get the value pairs
    over_values <- unlist(strsplit(over, split = ":", fixed = TRUE))[2L]
    over_pairs <- unlist(stringr::str_split(over_values, pattern = ","))
    # extract the COG sizes
    purrr::map(over_pairs, function(op) {
        xsize <- as.numeric(unlist(
            strsplit(op, split = "x", fixed = TRUE)
        )[[1L]])
        ysize <- as.numeric(unlist(
            strsplit(op, split = "x", fixed = TRUE)
        )[[2L]])
        c(xsize = xsize, ysize = ysize)
    })
}`

