const rtdal006856Source0017 = `.torch_as_dataset <- torch::dataset(
    "dataset",
    initialize = function(x) {
        self$x <- x
        self$dim <- dim(x)
    },
    .getitem = function(i) {
        if (length(self$dim) == 3L) {
            item_data <- self$x[i, , , drop = FALSE]
        } else {
            item_data <- self$x[i, , drop = FALSE]
        }

        list(torch::torch_tensor(
            array(item_data, dim = c(
                nrow(item_data), self$dim[2L:length(self$dim)]
            ))
        ))
    },
    .getbatch = function(i) {
        self$.getitem(i)
    },
    .length = function() {
        dim(self$x)[[1L]]
    }
)`

