const rtdal006881Source0001 = `sits_combine_predictions <- function(cubes, type = "average", ...) {
    # set caller for error msg
    .check_set_caller("sits_combine_predictions")
    # check if list of probs cubes have the same organization
    .check_probs_cube_lst(cubes)
    class(type) <- type
    UseMethod("sits_combine_predictions", type)
}`

const rtdal006881Source0002 = `sits_combine_predictions.average <- function(cubes,
                                             type = "average", ...,
                                             weights = NULL,
                                             memsize = 8L,
                                             multicores = 2L,
                                             output_dir,
                                             version = "v1",
                                             progress = FALSE) {
    # Check memsize
    .check_num_parameter(memsize, min = 1L, max = 16384L)
    # Check multicores
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    # Check output dir
    .check_output_dir(output_dir)
    # Check version and convert to lowercase
    # Check version and progress
    version <- .message_version(version)
    progress <- .message_progress(progress)
    # Get weights
    n_inputs <- length(cubes)
    weights <- .default(weights, rep(1L / n_inputs, n_inputs))
    .check_that(
        length(weights) == n_inputs,
        msg = .conf("messages", "sits_combine_predictions_weights")
    )
    .check_that(
        sum(weights) == 1.0,
        msg = .conf("messages", "sits_combine_predictions_sum_weights")
    )
    # Get combine function
    comb_fn <- .comb_fn_average(cubes, weights = weights)
    # Call combine predictions
    .comb(
        probs_cubes = cubes,
        uncert_cubes = NULL,
        comb_fn = comb_fn,
        band = "probs",
        memsize = memsize,
        multicores = multicores,
        output_dir = output_dir,
        version = version,
        progress = progress, ...
    )
}`

const rtdal006881Source0003 = `sits_combine_predictions.uncertainty <- function(cubes,
                                                 type = "uncertainty", ...,
                                                 uncert_cubes,
                                                 memsize = 8L,
                                                 multicores = 2L,
                                                 output_dir,
                                                 version = "v1",
                                                 progress = FALSE) {
    # Check memsize
    .check_num_parameter(memsize, min = 1L, max = 16384L)
    # Check multicores
    .check_num_parameter(multicores, min = 1L, max = 2048L)
    # Check output dir
    .check_output_dir(output_dir)
    # Check version and convert to lowercase
    # Check version and progress
    version <- .message_version(version)
    progress <- .message_progress(progress)
    # Check if list of probs cubes and uncert_cubes have the same organization
    .check_that(
        length(cubes) == length(uncert_cubes),
        msg = .conf("messages", "sits_combine_predictions_uncert_cubes")
    )
    .check_uncert_cube_lst(uncert_cubes)
    .check_cubes_same_size(cubes[[1L]], uncert_cubes[[1L]])
    # Get combine function
    comb_fn <- .comb_fn_uncertainty(cubes)
    # Call combine predictions
    .comb(
        probs_cubes = cubes,
        uncert_cubes = uncert_cubes,
        comb_fn = comb_fn,
        band = "probs",
        memsize = memsize,
        multicores = multicores,
        output_dir = output_dir,
        version = version,
        progress = progress, ...
    )
}`

