const rtdal006883Source0002 = `sits_to_csv.sits <- function(data, file = NULL) {
    # check the samples are valid
    .check_samples(data)
    data <- .samples_convert_to_sits(data)
    # check the file name is valid
    if (.has(file)) {
        .check_file(
            x = file,
            extensions = "csv",
            file_exists = FALSE
        )
    }
    # get metadata
    csv <- .csv_metadata_from_samples(data)
    # write the CSV file
    if (.has(file)) {
        utils::write.csv(csv, file, row.names = FALSE, quote = FALSE)
    }
    return(csv)
}`

const rtdal006883Source0003 = `sits_to_csv.tbl_df <- function(data, file) {
    if (all(.conf("sits_tibble_cols") %in% colnames(data))) {
        class(data) <- c("sits", class(data))
    } else {
        stop(.conf("messages", "sits_to_csv_default"))
    }
    sits_to_csv(data, file)
}`

const rtdal006883Source0004 = `sits_to_csv.default <- function(data, file) {
    data <- tibble::as_tibble(data)
    sits_to_csv(data, file)
}`

const rtdal006883Source0005 = `sits_timeseries_to_csv <- function(data, file = NULL) {
    # check the samples are valid
    .check_samples(data)
    data <- .samples_convert_to_sits(data)
    csv_1 <- .csv_metadata_from_samples(data)
    csv_2 <- .predictors(data)[-2L:0L]
    csv_ts <- dplyr::bind_cols(csv_1, csv_2)

    # write the CSV file
    if (.has(file)) {
        utils::write.csv(csv_ts,
            file,
            row.names = FALSE,
            quote = FALSE
        )
    } else {
        return(csv_ts)
    }
}`

