const rtdal006891Source0002 = `sits_whittaker <- function(data = NULL, lambda = 0.5) {
    filter_fun <- function(data) {
        if (inherits(data, "matrix")) {
            smooth_whit_mtx(data, lambda = lambda, length = ncol(data))
        } else {
            smooth_whit(data, lambda = lambda, length = length(data))
        }
    }
    filter_call <- function(data) {
        if (inherits(data, "sits")) {
            .apply_across(data = data, fn = filter_fun)
        } else {
            filter_fun(data)
        }
    }
    result <- .factory_function(data, filter_call)
    return(result)
}`

const rtdal006891Source0003 = `sits_sgolay <- function(data = NULL, order = 3L, length = 5L) {
    # compute filter coefficients once
    f_res <- .signal_sgolay_coef(p = order, n = length, ts = 1L)
    # function to be applied
    filter_fun <- function(data) {
        # calculate coefficients for sgolay
        if (inherits(data, "matrix")) {
            smooth_sg_mtx(
                data,
                f_res = f_res,
                p = order,
                n = length
            )
        } else {
            smooth_sg(
                data,
                f_res = f_res,
                p = order,
                n = length
            )
        }
    }
    filter_call <- function(data) {
        if (inherits(data, "sits")) {
            .apply_across(data = data, fn = filter_fun)
        } else {
            filter_fun(data)
        }
    }
    .factory_function(data, filter_call)
}`

