const rtdal006895Source0001 = `sits_get_probs <- function(cube, samples, window_size = NULL) {
    .check_set_caller("sits_get_probs")
    # Pre-conditions
    .check_is_probs_cube(cube)
    .check_raster_cube_files(cube)
    if (is.character(samples)) {
        class(samples) <- c(.file_ext(samples), class(samples))
    }
    UseMethod("sits_get_probs", samples)
}`

const rtdal006895Source0003 = `sits_get_probs.shp <- function(cube, samples, window_size = NULL) {
    .check_set_caller("sits_get_probs")
    # transform from shapefile to sf
    sf_shape <- .shp_transform_to_sf(shp_file = samples)
    # Get the geometry type
    geom_type <- as.character(sf::st_geometry_type(sf_shape)[[1L]])
    if (geom_type != "POINT") {
        stop(.conf("messages", "sits_get_probs_not_point"))
    }

    # Get a tibble with points
    samples <- .sf_point_to_latlong(sf_object = sf_shape)
    # get the data
    data <- .data_get_probs(
        cube = cube,
        samples = samples,
        window_size = window_size
    )
    return(data)
}`

