const rtdal006898Source0001 = `impute_linear <- function(data = NULL) {
    impute_fun <- function(data) {
        if (inherits(data, "matrix")) {
            linear_interp(data)
        } else {
            linear_interp_vec(data)
        }
    }
    .factory_function(data, impute_fun)
}`

const rtdal006898Source0002 = `impute_median <- function(data = NULL) {
    # Define impute function
    impute_fun <- function(data) {
        # Matrix
        if (inherits(data, "matrix")) {
            C_interp_median_mat(data)
        }

        # Vector implementation
        else {
            as.vector(
                C_interp_median_vec(data)
            )
        }
    }

    .factory_function(data, impute_fun)
}`

