const rtdal006903Source0001 = "sits_rfor <- function(samples = NULL, num_trees = 100L, mtry = NULL, ...) {\n    .check_set_caller(\"sits_rfor\")\n    # Function that trains a random forest model\n    train_fun <- function(samples) {\n        # Verifies if 'randomForest' package is installed\n        .check_require_packages(\"randomForest\")\n        # Checks 'num_trees'\n        .check_int_parameter(num_trees, min = 20L)\n        # Get labels (used later to ensure column order in result matrix)\n        labels <- .samples_labels(samples)\n        # Get predictors features\n        train_samples <- .predictors(samples)\n        # Post condition: is predictor data valid?\n        .check_predictors(pred = train_samples, samples = samples)\n        # determine number of random forest\n        n_features <- ncol(train_samples) - 2L\n        # Apply the 'mtry' default value of 'randomForest' package\n        if (.has(mtry)) {\n            # Checks 'mtry'\n            .check_int_parameter(mtry, min = 1L, max = n_features)\n        } else {\n            # set the default values of `mtry`\n            mtry <- floor(sqrt(n_features))\n        }\n        # Train a random forest model\n        model <- randomForest::randomForest(\n            x = .pred_features(train_samples),\n            y = as.factor(.pred_references(train_samples)),\n            samples = NULL, ntree = num_trees, mtry = mtry,\n            nodesize = 1L, localImp = TRUE, norm.votes = FALSE, ...,\n            na.action = stats::na.fail\n        )\n        # Function that predicts results\n        predict_fun <- function(values) {\n            # Verifies if randomForest package is installed\n            .check_require_packages(\"randomForest\")\n            # Used to check values (below)\n            input_pixels <- nrow(values)\n            # Do classification\n            values <- stats::predict(\n                object = model, newdata = values, type = \"prob\"\n            )\n            # Are the results consistent with the data input?\n            .check_processed_values(values, input_pixels)\n            # Reorder matrix columns if needed\n            if (any(labels != colnames(values))) {\n                values <- values[, labels]\n            }\n            values\n        }\n        # Set model class\n        predict_fun <- .set_class(\n            predict_fun, \"rfor_model\", \"sits_model\", class(predict_fun)\n        )\n        predict_fun\n    }\n    # If samples is informed, train a model and return a predict function\n    # Otherwise give back a train function to train model further\n    .factory_function(samples, train_fun)\n}"

const rtdal006903Source0002 = `sits_lightgbm <- function(samples = NULL,
                          boosting_type = "gbdt",
                          objective = "multiclass",
                          min_samples_leaf = 20,
                          max_depth = 6,
                          learning_rate = 0.1,
                          num_iterations = 100,
                          n_iter_no_change = 10,
                          validation_split = 0.2, ...) {

    # function that returns a model based on training data
    train_fun <- function(samples) {
        # Extract the predictors
        train_samples <- sits_predictors(samples)

        # find number of labels
        labels <- sits_labels(samples)
        n_labels <- length(labels)
        # lightGBM uses numerical labels starting from 0
        int_labels <- c(1:n_labels) - 1
        # create a named vector with integers match the class labels
        names(int_labels) <- labels

        # add number of classes to lightGBM params
        # split the data into training and validation datasets
        # create partitions different splits of the input data
        test_samples <- sits_pred_sample(train_samples,
                                         frac = validation_split
        )

        # Remove the lines used for validation
        sel <- !(train_samples$sample_id %in% test_samples$sample_id)
        train_samples <- train_samples[sel, ]

        # transform the training data to LGBM dataset
        lgbm_train_samples <- lightgbm::lgb.Dataset(
            data = as.matrix(train_samples[, -2:0]),
            label = unname(int_labels[train_samples[[2]]])
        )
        # transform the test data to LGBM dataset
        lgbm_test_samples <- lightgbm::lgb.Dataset(
            data = as.matrix(test_samples[, -2:0]),
            label = unname(int_labels[test_samples[[2]]])
        )
        # set the parameters for the lightGBM training
        lgb_params <- list(
            boosting_type = boosting_type,
            objective = objective,
            min_samples_leaf = min_samples_leaf,
            max_depth = max_depth,
            learning_rate = learning_rate,
            num_iterations = num_iterations,
            n_iter_no_change = n_iter_no_change,
            num_class = n_labels
        )
        # call method and return the trained model
        lgbm_model <- lightgbm::lgb.train(
            data    = lgbm_train_samples,
            valids  = list(test_data = lgbm_test_samples),
            params  = lgb_params,
            verbose = -1,
            ...
        )
        # serialize the model for parallel processing
        lgbm_model_string <- lgbm_model$save_model_to_string(NULL)
        # construct model predict closure function and returns
        predict_fun <- function(values) {
            # reload the model (unserialize)
            lgbm_model <- lightgbm::lgb.load(model_str = lgbm_model_string)
            # predict probabilities
            prediction <- stats::predict(lgbm_model,
                                         newdata = as.matrix(values),
                                         type = "response"
            )
            # adjust the names of the columns of the probs
            colnames(prediction) <- labels
            # retrieve the prediction results
            return(prediction)
        }
        # Set model class
        # This tells sits that the resulting function
        # will be handled as a prediction model
        class(predict_fun) <- c("lightgbm_model",
                                "sits_model",
                                class(predict_fun))
        return(predict_fun)
    }
    result <- sits_factory_function(samples, train_fun)
    return(result)
}`

const rtdal006903Source0003 = `sits_svm <- function(samples = NULL, formula = sits_formula_linear(),
                     scale = FALSE,
                     cachesize = 1000L,
                     kernel = "radial",
                     degree = 3L,
                     coef0 = 0L,
                     cost = 10.0,
                     tolerance = 0.001,
                     epsilon = 0.1,
                     cross = 10L, ...) {
    .check_set_caller("sits_svm")
    # Function that trains a support vector machine model
    train_fun <- function(samples) {
        # does not support working with DEM or other base data
        if (inherits(samples, "sits_base")) {
            stop(.conf("messages", "sits_train_base_data"), call. = FALSE)
        }
        # Verifies if e1071 package is installed
        .check_require_packages("e1071")
        # Get labels (used later to ensure column order in result matrix)
        labels <- .samples_labels(samples)
        # Get normalized training samples
        ml_stats <- .samples_stats(samples)
        # Get predictors features
        train_samples <- .predictors(samples)
        # Normalize predictors
        train_samples <- .pred_normalize(pred = train_samples, stats = ml_stats)
        # Post condition: is predictor data valid?
        .check_predictors(pred = train_samples, samples = samples)
        # Update formula parameter
        if (inherits(formula, "function")) {
            formula <- formula(train_samples)
        }
        # Train an svm model
        model <- e1071::svm(
            formula = formula, data = train_samples, scale = scale,
            kernel = kernel, degree = degree, cost = cost, coef0 = coef0,
            cachesize = cachesize, tolerance = tolerance, epsilon = epsilon,
            cross = cross, probability = TRUE, ..., na.action = stats::na.fail
        )
        # Function that predicts labels of input values
        predict_fun <- function(values) {
            # Verifies if e1071 package is installed
            .check_require_packages("e1071")
            # Used to check values (below)
            input_pixels <- nrow(values)
            # Performs data normalization
            values <- .pred_normalize(pred = values, stats = ml_stats)
            # Do classification
            values <- stats::predict(
                object = model, newdata = values, probability = TRUE
            )
            # Get the predicted probabilities
            values <- attr(values, "probabilities")
            # Are the results consistent with the data input?
            .check_processed_values(values, input_pixels)
            # Reorder matrix columns if needed
            if (any(labels != colnames(values))) {
                values <- values[, labels]
            }
            values
        }
        # Set model class
        predict_fun <- .set_class(
            predict_fun, "svm_model", "sits_model", class(predict_fun)
        )
        predict_fun
    }
    # If samples is informed, train a model and return a predict function
    # Otherwise give back a train function to train model further
    .factory_function(samples, train_fun)
}`

const rtdal006903Source0004 = `sits_xgboost <- function(samples = NULL,
                         learning_rate = 0.15,
                         min_split_loss = 1.0,
                         max_depth = 5L,
                         min_child_weight = 1.0,
                         max_delta_step = 1.0,
                         subsample = 0.85,
                         nfold = 5L,
                         nrounds = 100L,
                         nthread = 6L,
                         early_stopping_rounds = 20L,
                         verbose = FALSE) {
    .check_set_caller("sits_xgboost")
    # documentation mode? verbose is FALSE
    verbose <- .message_verbose(verbose)
    # Function that trains a xgb model
    train_fun <- function(samples) {
        # verifies if xgboost package is installed
        .check_require_packages("xgboost")
        # Get labels (used later to ensure column order in result matrix)
        labels <- .samples_labels(samples)
        # Get predictors features
        train_samples <- .predictors(samples)
        # Post condition: is predictor data valid?
        .check_predictors(pred = train_samples, samples = samples)
        # Transform labels to integer code before train
        code_labels <- seq_along(labels)
        names(code_labels) <- labels
        # Reference labels for each sample expressed as numerical values
        references <-
            unname(code_labels[.pred_references(train_samples)]) - 1L
        # Define the parameters of the model
        params <- list(
            booster = "gbtree", objective = "multi:softprob",
            eval_metric = "mlogloss", eta = learning_rate,
            gamma = min_split_loss, max_depth = max_depth,
            min_child_weight = min_child_weight,
            max_delta_step = max_delta_step, subsample = subsample,
            nthread = nthread,
            num_class = length(labels)
        )
        if (verbose) {
            verbose <- 1L
        } else {
            verbose <- 0L
        }
        # transform predictors in a xgb.DMatrix
        xgb_matrix <- xgboost::xgb.DMatrix(
            data = as.matrix(.pred_features(train_samples)),
            label = references
        )
        # train the model
        model <- xgboost::xgb.train(
            xgb_matrix, params = params, nrounds = nrounds, verbose = verbose
        )
        # Get best ntreelimit
        ntreelimit <- model[["best_ntreelimit"]]
        # Function that predicts labels of input values
        predict_fun <- function(values) {
            # Verifies if xgboost package is installed
            .check_require_packages("xgboost")
            # Used to check values (below)
            input_pixels <- nrow(values)
            # Do classification
            values <- stats::predict(
                object = model, as.matrix(values), iterationrange = ntreelimit
            )
            # Are the results consistent with the data input?
            .check_processed_values(values, input_pixels)
            # Update the columns names to labels
            colnames(values) <- labels
            values
        }
        # Set model class
        predict_fun <- .set_class(
            predict_fun, "xgb_model", "sits_model", class(predict_fun)
        )
        predict_fun
    }
    # If samples is informed, train a model and return a predict function
    # Otherwise give back a train function to train model further
    .factory_function(samples, train_fun)
}`

const rtdal006903Source0005 = "sits_formula_logref <- function(predictors_index = -2L:0L) {\n    # set caller to show in errors\n    .check_set_caller(\"sits_formula_logref\")\n\n    # store configuration information about model formula\n    sits_env[[\"model_formula\"]] <- \"log\"\n\n    # this function returns a formula like\n    # 'factor(reference~log(f1)+log(f2)+...+log(fn)' where f1, f2, ..., fn are\n    # the predictor fields given by the predictor index.\n    result_fun <- function(tb) {\n        .check_that(nrow(tb) > 0)\n        # if no predictors_index are given, assume all tb's fields are used\n        if (!.has(predictors_index)) {\n            predictors_index <- seq_len(nrow(tb))\n        }\n        # get predictors names\n        categories <- names(tb)[c(predictors_index)]\n        # compute formula result\n        stats::as.formula(paste0(\n            \"factor(label)~\",\n            paste0(paste0(\"log(`\", categories, \"`)\"),\n                collapse = \"+\"\n            )\n        ))\n    }\n    result_fun\n}"

const rtdal006903Source0006 = `sits_formula_linear <- function(predictors_index = -2L:0L) {
    # set caller to show in errors
    .check_set_caller("sits_formula_linear")

    # store configuration information about model formula
    sits_env[["model_formula"]] <- "linear"

    # this function returns a formula
    # 'factor(reference~log(f1)+log(f2)+...+log(fn)' where f1, f2, ..., fn are
    #  the predictor fields.
    result_fun <- function(tb) {
        .check_content_data_frame(tb)
        n_rows_tb <- nrow(tb)
        # if no predictors_index are given, assume that all fields are used
        if (!.has(predictors_index)) {
            predictors_index <- seq_len(n_rows_tb)
        }

        # get predictors names
        categories <- names(tb)[c(predictors_index)]

        # compute formula result
        stats::as.formula(paste(
            "factor(label)~",
            paste(paste(categories,
                collapse = "+"
            ))
        ))
    }
    result_fun
}`

