const rtdal006910Source0016 = `plot.sits_accuracy <- function(x, y, ..., type = "confusion_matrix") {
    stopifnot(missing(y))
    if (!inherits(x, "sits_accuracy")) {
        message(.conf("messages", ".plot_sits_accuracy"))
        return(invisible(NULL))
    }
    data <- x
    if (type == "metrics") {
        # Extract metrics by class
        by_class <- data$byClass
        # remove "Class:  " from rownames
        rownames(by_class) <- stringr::str_replace(rownames(by_class),
                                                   "Class: ", "")
        # Convert to data frame
        by_class_long <- data.frame(
            Class = rownames(by_class),
            by_class
        )

        # Convert to tidy long format
        by_class_long_tidy <- by_class_long |>
            tidyr::pivot_longer(
                cols = -Class,
                names_to = "Metric",
                values_to = "Value"
            )

        # Important metrics for visualization
        important_metrics <- c(
            "Precision", "Recall", "F1"
        )

        by_class_filtered <- by_class_long_tidy |>
            dplyr::filter(.data[["Metric"]] %in% important_metrics)

        # Rename metrics for presentation
        metric_names <- c(
            "Precision" = "User Acc",
            "Recall" = "Prod Acc",
            "F1" = "F1-Score"
        )

        by_class_filtered$Metric <- metric_names[by_class_filtered$Metric]

        # Create heatmap of metrics by class
        p <- ggplot2::ggplot(by_class_filtered, ggplot2::aes(
            x = Metric, y = Class,
            fill = Value
        )) +
            ggplot2::geom_tile(color = "white", linewidth = 1) +
            ggplot2::scale_fill_gradient2(
                low = "#d32f2f", mid = "#fff9c4",
                high = "#388e3c", midpoint = 0.5,
                name = "Value",
                limits = c(0, 1),
                breaks = seq(0, 1, 0.2),
                labels = paste0(seq(0, 1, 0.2) * 100, "%")
            ) +
            ggplot2::geom_text(ggplot2::aes(label = round(Value, 2)),
                               size = 3.8,
                               fontface = "bold", color = "black"
            ) +
            ggplot2::labs(
                title = paste("Metrics by Class")
            ) +
            ggplot2::theme_minimal(base_size = 14) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(
                    hjust = 0.5, size = 16,
                    face = "bold",
                    margin = ggplot2::margin(b = 15)
                ),
                axis.text.x = ggplot2::element_text(
                    angle = 45, hjust = 1,
                    size = 11, face = "bold"
                ),
                axis.text.y = ggplot2::element_text(
                    size = 11, face = "bold"),
                axis.title = ggplot2::element_text(
                    size = 13, face = "bold",
                    margin = ggplot2::margin(t = 10)
                ),
                legend.title = ggplot2::element_text(size = 12, face = "bold"),
                legend.text  = ggplot2::element_text(size = 11),
                panel.grid   = ggplot2::element_blank(),
                plot.margin  = ggplot2::margin(15, 15, 15, 15)
            )
        graphics::plot(p)
    }
    else {
        # Extract confusion matrix
        cm_mat <- as.matrix(data$table)

        # Transform to data frame for ggplot
        cm_long <- as.data.frame(as.table(cm_mat))

        # Order Prediction factor levels
        cm_long$Prediction <- factor(cm_long$Prediction,
                                     levels = unique(cm_long$Prediction)
        )

        # Order Reference factor levels
        cm_long$Reference <- factor(cm_long$Reference,
                                    levels = unique(cm_long$Reference)
        )

        # Create visualization with ggplot
        p <- ggplot2::ggplot(cm_long, ggplot2::aes(
            x = Reference, y = Prediction,
            fill = Freq
        )) +
            ggplot2::geom_tile(color = "white", linewidth = 1.2) +
            ggplot2::geom_text(ggplot2::aes(label = Freq),
                               color = "black",
                               linewidth = 4.2, fontface = "bold"
            ) +
            ggplot2::scale_fill_gradient(
                low = "#f1f3f4", high = "#1976d2",
                name = "Cases", trans = "sqrt"
            ) +
            ggplot2::scale_y_discrete(limits = rev(levels(cm_long$Prediction))) +
            ggplot2::theme_minimal(base_size = 14) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(
                    hjust = 0.5, size = 16, face = "bold",
                    margin = ggplot2::margin(b = 20)
                ),
                axis.text.x = ggplot2::element_text(
                    angle = 45, hjust = 1, size = 11,
                    face = "bold"
                ),
                axis.text.y = ggplot2::element_text(
                    size = 11, face = "bold"),
                axis.title = ggplot2::element_text(
                    size = 13, face = "bold",
                    margin = ggplot2::margin(t = 10)
                ),
                legend.title = ggplot2::element_text(
                    size = 12, face = "bold"),
                legend.text = ggplot2::element_text(size = 11),
                panel.grid = ggplot2::element_blank(),
                plot.margin = ggplot2::margin(20, 20, 20, 20)
            ) +
            ggplot2::labs(
                title = "Confusion Matrix",
                x = "Reference",
                y = "Predicted"
            )
        graphics::plot(p)
    }
    p
}`

const rtdal006910Source0017 = `plot.som_evaluate_cluster <- function(x, y, ...,
                                      legend = NULL,
                                      name_cluster = NULL,
                                      title = "Confusion by cluster") {
    stopifnot(missing(y))
    data <- x
    if (!inherits(data, "som_evaluate_cluster")) {
        message(.conf("messages", ".plot_som_evaluate_cluster"))
        return(invisible(NULL))
    }

    # Filter the cluster to plot
    if (!(is.null(name_cluster))) {
        data <- dplyr::filter(data, .data[["cluster"]] %in% name_cluster)
    }
    # configure plot colors
    # get labels from cluster table
    labels <- unique(data[["class"]])
    colors <- .colors_get(
        labels = labels,
        legend = legend,
        palette = "Spectral",
        rev = TRUE
    )

    # Optional ordering of clusters or classes by dominant mixture (clearer visual interpretation)
    # Calculate dominant class by cluster
    dominant <- data |>
        dplyr::group_by(.data[["cluster"]], class) |>
        dplyr::summarise(
            total =
                sum(.data[["mixture_percentage"]]), .groups = "drop"
        ) |>
        dplyr::group_by(.data[["cluster"]]) |>
        dplyr::slice_max(.data[["total"]], n = 1) |>
        dplyr::arrange(dplyr::desc(.data[["total"]])) |>
        dplyr::pull(.data[["cluster"]]) |>
        unique() #

    # convert some elements in factor and filter percentage for plot
    data_conv <- data |>
        # Show labels only for percentages greater than 3%
        # (for better visualization)
        dplyr::mutate(
            label = ifelse(.data[["mixture_percentage"]] < 3, NA,
                .data[["mixture_percentage"]]
            ),
            class = as.factor(class),
            cluster = factor(.data[["cluster"]], levels = dominant)
        )

    # Stacked bar graphs for confusion by cluster
    g <- ggplot2::ggplot(
        data_conv,
        ggplot2::aes(
            x = .data[["mixture_percentage"]],
            y = factor(.data[["cluster"]],
                levels = rev(levels(.data[["cluster"]]))
            ),
            fill = class
        )
    ) +
        ggplot2::geom_bar(
            stat = "identity",
            color = "white",
            width = 0.9
        ) +
        ggplot2::geom_text(
            ggplot2::aes(
                label = scales::percent(label / 100, 1)
            ),
            position = ggplot2::position_stack(vjust = 0.5),
            color = "black",
            size = 3.5,
            fontface = "bold",
            check_overlap = TRUE
        ) +
        ggplot2::theme_classic() +
        ggplot2::theme(
            axis.title.y = ggplot2::element_text(size = 11),
            legend.title = ggplot2::element_text(size = 11),
            legend.text = ggplot2::element_text(size = 9),
            legend.key.size = ggplot2::unit(0.5, "cm"),
            legend.spacing.y = ggplot2::unit(0.5, "cm"),
            legend.position = "right",
            legend.justification = "center"
        ) +
        ggplot2::xlab("Percentage of mixture") +
        ggplot2::ylab("Class") +
        ggplot2::scale_fill_manual(
            values = colors,
            name = "Class label"
        ) +
        ggplot2::ggtitle(title)

    return(g)
}`

const rtdal006910Source0018 = `plot.som_map <- function(x, y, ...,
                         type = "codes",
                         legend = NULL,
                         band = NULL) {
    stopifnot(missing(y))
    koh <- x
    if (!inherits(koh, "som_map")) {
        message(.conf("messages", ".plot_som_map"))
        return(invisible(NULL))
    }
    # set band
    bands <- names(koh[["som_properties"]][["codes"]])
    # check if band name is available
    if (.has(band)) {
        .check_band_in_bands(band, bands)
        # create a numeric vector for plotting
        bands_koh <- seq_along(bands)
        names(bands_koh) <- bands
        whatmap <- bands_koh[[band]]
    } else {
        whatmap <- 1L
    }


    # paint neurons
    koh <- .som_paint_neurons(koh, legend)
    if (type == "mapping") {
        graphics::plot(koh[["som_properties"]],
            bgcol = koh[["som_properties"]][["paint_map"]],
            "mapping", whatmap = whatmap,
            codeRendering = "lines"
        )
    } else if (type == "codes") {
        graphics::plot(koh[["som_properties"]],
            bgcol = koh[["som_properties"]][["paint_map"]],
            "codes", whatmap = whatmap,
            codeRendering = "lines"
        )
    }

    # create a legend
    leg <- cbind(
        koh[["som_properties"]][["neuron_label"]],
        koh[["som_properties"]][["paint_map"]]
    )
    graphics::legend(
        "bottomright",
        legend = unique(leg[, 1L]),
        col = unique(leg[, 2L]),
        pch = 15L,
        pt.cex = 2L,
        cex = 1L,
        text.col = "black",
        inset = c(0.0095, 0.05),
        xpd = TRUE,
        ncol = 1L
    )
    return(invisible(x))
}`

const rtdal006910Source0019 = `plot.som_clean_samples <- function(x, ...) {
    .check_set_caller(".plot_som_clean_samples")

    # retrieve the evaluation labels
    eval_labels <- unique(x[["eval"]])
    # check if all eval labels are available
    all_evals <- all(c("clean", "analyze", "remove")
    %in% eval_labels)
    if (!all_evals) {
        warning(.conf("messages", ".plot_som_clean_samples"))
    }
    # organize the evaluation by class and percentage
    eval <- x |>
        dplyr::group_by(.data[["label"]], .data[["eval"]]) |>
        dplyr::summarise(n = dplyr::n()) |>
        dplyr::mutate(n_class = sum(.data[["n"]])) |>
        dplyr::ungroup() |>
        dplyr::mutate(percent = (.data[["n"]] / .data[["n_class"]]) * 100.0) |>
        dplyr::select(
            dplyr::all_of("label"),
            dplyr::all_of("eval"),
            dplyr::all_of("percent")
        ) |>
        tidyr::pivot_wider(
            names_from = .data[["eval"]],
            values_from = .data[["percent"]]
        )

    colors_eval <- c("#C7BB3A", "#4FC78E", "#D98880")
    if (all_evals) {
        eval <- eval |>
            dplyr::select(c("label", "clean", "remove", "analyze")) |>
            tidyr::replace_na(list(clean = 0.0, remove = 0.0, analyze = 0.0))

        pivot <- tidyr::pivot_longer(eval,
            cols = c("clean", "remove", "analyze"),
            names_to = "Eval", values_to = "value"
        )
    } else {
        eval <- eval |>
            dplyr::select(c("label", "clean", "analyze")) |>
            tidyr::replace_na(list(clean = 0.0, analyze = 0.0))
        pivot <- tidyr::pivot_longer(eval,
            cols = c("clean", "analyze"),
            names_to = "Eval", values_to = "value"
        )
        colors_eval <- c("#C7BB3A", "#4FC78E")
    }

    sample_labels <- unique(pivot[["label"]])
    pivot$label <- factor(pivot$label, levels = sample_labels)

    # Stacked bar graphs for Noise Detection
    g <- ggplot2::ggplot(
        pivot,
        ggplot2::aes(
            x = value,
            y = factor(label, levels = rev(levels(label))),
            fill = Eval
        )
    ) +
        ggplot2::geom_bar(
            stat = "identity",
            color = "white",
            width = 0.9
        ) +
        ggplot2::geom_text(
            ggplot2::aes(
                label = scales::percent(value / 100.0, 1L)
            ),
            position = ggplot2::position_stack(vjust = 0.5),
            color = "black",
            size = length(eval_labels),
            fontface = "bold",
            check_overlap = TRUE
        ) +
        ggplot2::theme_classic() +
        ggplot2::theme(
            axis.title.y = ggplot2::element_blank(),
            legend.title = ggplot2::element_text(size = 11L),
            legend.text = ggplot2::element_text(size = 9L),
            legend.key.size = ggplot2::unit(0.5, "cm"),
            legend.spacing.y = ggplot2::unit(0.5, "cm"),
            legend.position = "right",
            legend.justification = "center"
        ) +
        ggplot2::xlab("%") +
        ggplot2::scale_fill_manual(
            values = colors_eval,
            name = "Evaluation"
        ) +
        ggplot2::ggtitle("Class noise detection")
    g
}`

